_FILES['config.py'] = '"""\nConfiguration — Indiana Accident Forecaster v2 (county-based).\n\nSpatial unit: county. The baseline layer is EMS-derived motor-vehicle\ninjury opportunity (data/county_opportunity.csv, built from Indiana Data\nHub EMS incidents with severity weighting). The top DYNAMIC_N counties by\nopportunity get live weather + incident monitoring; the long tail stays at\nits static baseline.\n"""\n\nCOUNTY_CSV = "data/county_opportunity.csv"\nPHASE2_PRIORITY_CSV = "data/phase2_metro_priority.csv"\nPHASE2_EFFICIENCY_CSV = "data/phase2_cluster_metro_efficiency.csv"\n\nDYNAMIC_N = 92  # all counties get live weather (Open-Meteo requests are\n#   batched: one call covers every county, so statewide costs the same as\n#   25 did). Incidents are county-assigned statewide via boundary polygons.\n\n# FALLBACK county centroids (lat, lon), used for weather sampling and\n# nearest-county incident assignment only when the county-boundary\n# download fails; normally all 92 centroids are derived from the\n# boundary polygons at runtime.\nCOUNTY_CENTROIDS = {\n    "Marion": (39.78, -86.14), "Allen": (41.09, -85.07),\n    "Lake": (41.42, -87.37), "Hamilton": (40.07, -86.05),\n    "Elkhart": (41.60, -85.87), "St. Joseph": (41.62, -86.29),\n    "Tippecanoe": (40.39, -86.89), "Hendricks": (39.77, -86.51),\n    "Vanderburgh": (38.02, -87.59), "Bartholomew": (39.20, -85.90),\n    "Johnson": (39.49, -86.10), "Delaware": (40.23, -85.40),\n    "Porter": (41.46, -87.07), "Madison": (40.16, -85.72),\n    "Kosciusko": (41.24, -85.86), "Monroe": (39.16, -86.52),\n    "Hancock": (39.82, -85.77), "Noble": (41.40, -85.42),\n    "Vigo": (39.43, -87.39), "Cass": (40.76, -86.35),\n    "Boone": (40.05, -86.47), "Lagrange": (41.64, -85.43),\n    "Marshall": (41.32, -86.26), "Jackson": (38.91, -86.04),\n    "Laporte": (41.55, -86.74),\n}\n\n# County -> Phase 2 metro mapping (for blending with the static search-\n# economics shares). Counties not listed roll into "other_in".\nCOUNTY_TO_METRO = {\n    "Marion": "indianapolis", "Hamilton": "indianapolis",\n    "Hendricks": "indianapolis", "Johnson": "indianapolis",\n    "Boone": "indianapolis", "Hancock": "indianapolis",\n    "Madison": "indianapolis", "Morgan": "indianapolis",\n    "Shelby": "indianapolis",\n    "Allen": "fortwayne", "Whitley": "fortwayne", "Wells": "fortwayne",\n    "Noble": "fortwayne", "Dekalb": "fortwayne", "Huntington": "fortwayne",\n    "Lake": "nwindiana", "Porter": "nwindiana", "Laporte": "nwindiana",\n    "Jasper": "nwindiana", "Newton": "nwindiana",\n    "St. Joseph": "southbend", "Elkhart": "southbend",\n    "Marshall": "southbend", "Kosciusko": "southbend",\n    "Lagrange": "southbend",\n    "Tippecanoe": "lafayette", "Clinton": "lafayette",\n    "White": "lafayette", "Carroll": "lafayette",\n    "Vanderburgh": "evansville", "Warrick": "evansville",\n    "Posey": "evansville", "Gibson": "evansville",\n}\n\nOPEN_METEO_URL = "https://api.open-meteo.com/v1/forecast"\n\n# --- 511in.org live incidents ---------------------------------------------\n# Primary: the same GraphQL endpoint the public 511in.org map uses (verified\n# via browser DevTools, July 2026). Anonymous requests are attempted first;\n# the site\'s own map issues short-lived visitor tokens, so nothing is\n# hardcoded here. Statewide bbox; server-side clusters are drilled into by\n# re-querying each cluster\'s bbox at its maxZoom+1 (bounded by\n# GRAPHQL_MAX_REQUESTS per run).\nGRAPHQL_URL = "https://511in.org/api/graphql"\nGRAPHQL_LAYERS = ["incidents"]\nSTATE_BBOX = {"north": 41.95, "south": 37.65, "east": -84.55, "west": -88.25}\nGRAPHQL_MAX_REQUESTS = 25\n\n# Legacy fallbacks (kept for graceful degradation; the api/v2 endpoint is\n# the IBI-platform standard used by other states and is NOT expected to\n# work for Indiana — see [warn] lines in logs).\nTRAFFICWISE_EVENTS_URLS = [\n    "https://511in.org/api/v2/get/event?format=json",\n    "https://content.trafficwise.org/json/cars.json",\n]\nTRAFFICWISE_API_KEY = None  # legacy; unused unless api/v2 ever works\n\n# --- TomTom Traffic Incidents (local-road coverage) ------------------------\n# Blended with 511. 511\'s real gap is geography (INDOT-managed roads only);\n# TomTom\'s probe data adds local-road incidents statewide. Requires a free\n# TomTom developer key stored as the TOMTOM_API_KEY GitHub Actions secret\n# (the workflow exports it as an env var). If the env var is absent the\n# feed is skipped and everything runs exactly as before.\nTOMTOM_URL = "https://api.tomtom.com/traffic/services/5/incidentDetails"\nTOMTOM_TILE_MAX_KM2 = 9750  # API bbox cap is 10,000 km^2; safety margin.\n#   The fetcher solves for the fewest tiles that stay under this\n#   (16 for Indiana\'s bbox vs 20 with the old fixed 1-degree grid) and\n#   skips tiles that don\'t overlap any Indiana county.\nTOMTOM_MAX_REQUESTS = 24   # hard per-run cap, belt-and-suspenders\n# TomTom snapshot cache: incidents there are long-lived (jams, closures,\n# roadwork persist for hours), so between refreshes the last statewide\n# snapshot is reused — the layer never goes blank, requests drop ~60%.\n# Fast-moving crash reports are covered by the 5-minute 511 polls.\nTOMTOM_REFRESH_DAY_MIN = 35     # refetch when snapshot older (6am-10pm)\nTOMTOM_REFRESH_NIGHT_MIN = 65   # overnight traffic changes slowly\nTOMTOM_DEDUP_KM = 1.5      # drop TomTom events this close to a 511 event\n\n# If the GitHub Actions poller is set up, its raw incident-history URL,\n# e.g. "https://raw.githubusercontent.com/USER/REPO/main/incident_history.json"\n# Colab runs will merge this machine-built archive into local memory.\nINCIDENT_LOG_URL = None\n\n# Weather multipliers (FHWA road-weather program; Qiu & Nixon 2008;\n# Theofilatos & Yannis 2014 — conservative midpoints).\nWEATHER_MULTIPLIERS = {\n    "rain_light": 1.25, "rain_moderate": 1.5, "rain_heavy": 1.8,\n    "snow_light": 1.5, "snow_moderate": 1.8, "snow_heavy": 2.2,\n    "freezing_precip": 2.5, "fog": 1.4, "darkness": 1.25, "high_wind": 1.15,\n}\nMAX_MULTIPLIER = 3.5\nINCIDENT_BOOST_PER_EVENT = 0.10   # +10% county risk per unit of\n#   severity-weighted live activity: crash=1.0, closure/hazard=0.6,\n#   stalled=0.4, congestion=0.3, roadwork=0.15, \'reopened\'=ignored.\n#   See EVENT_WEIGHTS in sources.py.\n# Collisions vs contributing factors: only events with weight >= this get\n# a map marker. 1.0 = crashes only (incl. "road closed due to crash",\n# which classifies as crash). Lower to 0.6 to also mark hazards (ice,\n# flooding, spills). Everything below the bar still shades its county\'s\n# color and is itemized in the county click-panel.\nMAP_MIN_MARKER_WEIGHT = 1.0\n# Events below this weight never enter trailing memory (roadwork and\n# congestion have near-zero trailing signal but would bloat\n# incident_history.json now that TomTom reports them statewide).\nMEMORY_MIN_WEIGHT = 0.4\n\n# --- long-term crash ledger (learned county baselines) ----------------------\n# Every crash the feeds ever record is tallied by county+month inside\n# incident_history.json (key "_ledger"). Once the statewide sample passes\n# LEDGER_MIN_TOTAL, observed county shares gently adjust the EMS baseline\n# via an empirical-Bayes factor; PRIOR_K shrinks small samples toward 1.0\n# and CAP bounds the effect (the feeds over-represent highways and metro\n# roads, so the EMS baseline must remain the anchor).\n# --- vehicle-type county badges ---------------------------------------------\n# Truck involvement IS visible in feed text ("semi", "jackknifed", ...) so\n# 🚛 badges are learned from the crash archive once a county has enough\n# data. Rideshare involvement is NEVER visible in any traffic feed, so 🚕\n# badges come only from the manual list — fill it from the firm\'s own\n# case history (county names exactly as in the opportunity table).\nTRUCK_KEYWORDS = ("semi", "tractor trailer", "tractor-trailer", "jackknif",\n                  "big rig", "18 wheeler", "18-wheeler", "commercial vehicle",\n                  " cmv", "box truck", "dump truck", "truck")\nTRUCK_BADGE_MIN_N = 5         # crashes (baseline + archive) before judging\nTRUCK_BADGE_MIN_SHARE = 0.15  # truck share required (statewide avg ~7%,\n#   so 15%+ marks a county genuinely tilted toward truck crashes)\n# Official background data: drop a baseline_crashes.csv in the repo root\n# (columns: county,total_crashes,truck_crashes — from the ICJI/IU-PPI\n# ARIES county profiles) and badges blend it with the live archive.\nBASELINE_CRASH_CSV = "baseline_crashes.csv"\nTRUCK_COUNTIES_MANUAL: list[str] = []      # e.g. ["Jasper", "Newton"]\nRIDESHARE_COUNTIES_MANUAL: list[str] = []  # e.g. ["Marion", "Hamilton"]\n\nLEDGER_MIN_TOTAL = 300\nLEDGER_PRIOR_K = 25.0\nLEDGER_CAP = (0.75, 1.30)\n\nTRAILING_BOOST_PER_POINT = 0.05   # +5% per point of decayed trailing weight\nINCIDENT_BOOST_CAP = 1.75         # cap on combined live + trailing boost\nTRAILING_HALF_LIFE_H = 48         # trailing importance halves every 48 h\n\n# Hour-of-week exposure fallback (INDOT diurnal shape). Upgrade path: learn\n# this empirically from EMS run timestamps if a filtered extract with a\n# datetime column is provided.\nWEEKDAY_HOURLY = [0.25,0.15,0.12,0.12,0.25,0.6,1.3,1.9,1.6,1.2,1.15,1.25,\n                  1.35,1.35,1.5,1.8,2.0,2.1,1.6,1.1,0.85,0.7,0.55,0.4]\nWEEKEND_HOURLY = [0.45,0.3,0.25,0.15,0.15,0.25,0.45,0.7,1.0,1.3,1.5,1.6,\n                  1.65,1.6,1.55,1.5,1.45,1.4,1.3,1.1,0.95,0.8,0.7,0.55]\n\n# Budget blending: forecast may move up to this fraction of allocation away\n# from the static Phase 2 shares.\nDYNAMIC_WEIGHT = 0.35\nSTATIC_SHARES = {\n    "indianapolis": 0.50, "fortwayne": 0.15, "nwindiana": 0.13,\n    "southbend": 0.10, "lafayette": 0.06, "evansville": 0.06,\n}\n'
_FILES['sources.py'] = '"""\nData connectors (v2): county opportunity table, batched Open-Meteo\nforecasts for the dynamic counties, 511/CARS live incidents.\n\nAll network connectors degrade gracefully to neutral values so a\nscheduled run always completes.\n"""\nfrom __future__ import annotations\n\nimport datetime as dt\nimport math\nimport os\nimport sys\n\nimport pandas as pd\nimport requests\n\nimport config\n\n\ndef load_counties() -> pd.DataFrame:\n    df = pd.read_csv(config.COUNTY_CSV)\n    df["county"] = df["county"].astype(str).str.strip()\n    if "weighted_score" in df.columns and "opportunity_score" in df.columns:\n        # Retire the synthetic viability multiplier (opportunity_score was\n        # weighted_score * (0.5 + viability); viability itself derived from\n        # a synthetic pct_non_english column built in early prototyping).\n        # Anchor purely on the EMS-derived weighted_score and re-rank.\n        df["opportunity_score"] = df["weighted_score"].astype(float)\n        df = df.sort_values("opportunity_score",\n                            ascending=False).reset_index(drop=True)\n        if "rank" in df.columns:\n            df["rank"] = range(1, len(df) + 1)\n        df = df.drop(columns=[c for c in ("viability", "pct_non_english")\n                              if c in df.columns])\n        print("[info] synthetic viability/pct_non_english columns retired: "\n              "opportunity_score = EMS weighted_score "\n              f"({len(df)} counties re-ranked)")\n    df["dynamic"] = False\n    dyn = df.nlargest(config.DYNAMIC_N, "opportunity_score")["county"]\n    df.loc[df["county"].isin(dyn), "dynamic"] = True\n    df["metro"] = df["county"].map(config.COUNTY_TO_METRO).fillna("other_in")\n    return df\n\n\n# ---------------------------------------------------------------------------\n# Weather — one batched request for all dynamic counties\n# ---------------------------------------------------------------------------\nHOURLY_VARS = ["precipitation", "snowfall", "temperature_2m", "visibility",\n               "wind_gusts_10m", "is_day", "weather_code"]\n\n\ndef county_centroids(geodata, county_names) -> dict:\n    """{canonical county name: (lat, lon)} for all counties, derived from\n    the boundary polygons; falls back to the hand-entered top-25 table\n    when boundaries are unavailable."""\n    if not geodata:\n        return dict(config.COUNTY_CENTROIDS)\n    canon = {_norm_name(n): n for n in (county_names or [])}\n    out = {}\n    for fips, cen in (geodata.get("centroids") or {}).items():\n        name = geodata["fips_to_name"].get(fips, fips)\n        out[canon.get(_norm_name(name), name)] = cen\n    return out or dict(config.COUNTY_CENTROIDS)\n\n\ndef fetch_weather(hours: int = 48,\n                  centroids: dict | None = None) -> dict[str, pd.DataFrame]:\n    cents = centroids or config.COUNTY_CENTROIDS\n    names = list(cents)\n    lats = ",".join(str(cents[n][0]) for n in names)\n    lons = ",".join(str(cents[n][1]) for n in names)\n    params = {\n        "latitude": lats, "longitude": lons,\n        "hourly": ",".join(HOURLY_VARS),\n        "forecast_days": min(7, max(1, math.ceil(hours / 24))),\n        "timezone": "America/Indiana/Indianapolis",\n    }\n    out = {}\n    try:\n        r = requests.get(config.OPEN_METEO_URL, params=params, timeout=30)\n        r.raise_for_status()\n        payload = r.json()\n        if isinstance(payload, dict):  # single-location fallback\n            payload = [payload]\n        for name, loc in zip(names, payload):\n            df = pd.DataFrame(loc["hourly"])\n            df["time"] = pd.to_datetime(df["time"])\n            df = df.set_index("time").iloc[:hours]\n            df["freezing_precip_flag"] = df["weather_code"].isin(\n                [56, 57, 66, 67])\n            out[name] = df\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] weather fetch failed ({e}); using neutral weather.",\n              file=sys.stderr)\n    for name in names:  # fill any gaps\n        out.setdefault(name, neutral_weather(hours))\n    return out\n\n\ndef neutral_weather(hours: int) -> pd.DataFrame:\n    idx = pd.date_range(dt.datetime.now().replace(minute=0, second=0,\n                                                  microsecond=0),\n                        periods=hours, freq="h")\n    return pd.DataFrame({\n        "precipitation": 0.0, "snowfall": 0.0, "temperature_2m": 15.0,\n        "visibility": 20000.0, "wind_gusts_10m": 10.0, "is_day": 1,\n        "weather_code": 0, "freezing_precip_flag": False,\n    }, index=idx)\n\n\ndef weather_multiplier(row: pd.Series) -> float:\n    m = config.WEATHER_MULTIPLIERS\n    mult = 1.0\n    snow = row.get("snowfall", 0.0)        # cm/h\n    rain = row.get("precipitation", 0.0)   # mm/h\n    if row.get("freezing_precip_flag", False) or (\n            rain > 0.1 and row.get("temperature_2m", 15) <= 0):\n        mult *= m["freezing_precip"]\n    elif snow > 2.5:\n        mult *= m["snow_heavy"]\n    elif snow > 1.0:\n        mult *= m["snow_moderate"]\n    elif snow > 0.1:\n        mult *= m["snow_light"]\n    elif rain > 7.6:\n        mult *= m["rain_heavy"]\n    elif rain > 2.5:\n        mult *= m["rain_moderate"]\n    elif rain > 0.1:\n        mult *= m["rain_light"]\n    if row.get("visibility", 20000) < 1000:\n        mult *= m["fog"]\n    if not row.get("is_day", 1):\n        mult *= m["darkness"]\n    if row.get("wind_gusts_10m", 0) > 40:\n        mult *= m["high_wind"]\n    return min(mult, config.MAX_MULTIPLIER)\n\n\n# ---------------------------------------------------------------------------\n# Live incidents -> per-county active event counts\n# ---------------------------------------------------------------------------\n# Substance-based event classification. Order matters: first match wins.\n# weight 0.0 = not a risk signal at all (dropped entirely: no boost, no\n# marker, no memory).\nEVENT_WEIGHTS = [\n    ("reopened/cleared", 0.0, (\n        "back open", "reopened", "re-opened", "all lanes open",\n        "has been cleared", "now open", "open to traffic", "has ended")),\n    ("crash", 1.0, (\n        "crash", "accident", "collision", "overturned", "jackknif",\n        "pileup", "multi vehicle", "multi-vehicle", "rollover")),\n    ("stalled/disabled", 0.4, (\n        "stalled", "disabled vehicle", "vehicle fire", "abandoned vehicle")),\n    ("closure/hazard", 0.6, (\n        "road closed", "ramp closed", "bridge closed", "closed in both",\n        "closure", "hazmat", "spill", "debris", "flood", "high water",\n        "fire", "downed", "ice", "snow covered")),\n    ("congestion", 0.3, (\n        "slow traffic", "congestion", "delay", "stopped traffic",\n        "heavy traffic", "backup")),\n    ("roadwork", 0.15, (\n        "construction", "roadwork", "road work", "maintenance",\n        "restriction", "lane closed", "lane closure", "paving",\n        "bridge work", "mowing", "utility work", "shoulder work")),\n]\nDEFAULT_EVENT_CATEGORY = ("other", 0.3)\n\n\ndef classify_event(text: str) -> tuple[str, float]:\n    """(category, risk weight) from an event\'s title + description."""\n    t = str(text).lower()\n    for cat, w, kws in EVENT_WEIGHTS:\n        if any(k in t for k in kws):\n            return cat, w\n    return DEFAULT_EVENT_CATEGORY\n\n\ndef _norm_bbox(cb):\n    """Cluster bbox -> (north, south, east, west); tolerates dict or\n    GeoJSON-style [west, south, east, north] list."""\n    if isinstance(cb, dict):\n        return (float(cb["north"]), float(cb["south"]),\n                float(cb["east"]), float(cb["west"]))\n    w, s, e, n = (float(x) for x in cb)\n    return (n, s, e, w)\n\n\ndef _feature_point(mf):\n    """First usable (lat, lon) from a mapFeature\'s GeoJSON geometries."""\n    for feat in (mf.get("features") or []):\n        g = feat.get("geometry") or {}\n        t, c = g.get("type"), g.get("coordinates")\n        if not c:\n            continue\n        if t == "Point":\n            return (float(c[1]), float(c[0]))\n        if t in ("MultiPoint", "LineString"):\n            return (float(c[0][1]), float(c[0][0]))\n        if t in ("MultiLineString", "Polygon"):\n            return (float(c[0][0][1]), float(c[0][0][0]))\n    return None\n\n\ndef _graphql_map_features(session, bbox, zoom):\n    """One MapFeatures query against the 511in.org GraphQL endpoint."""\n    payload = {\n        "query": (\n            "query MapFeatures($input: MapFeaturesArgs!) {"\n            " mapFeaturesQuery(input: $input) { mapFeatures {"\n            " bbox title tooltip uri"\n            " features { id geometry properties }"\n            " ... on Cluster { maxZoom } ... on Event { priority }"\n            " __typename } error { message type } } }"),\n        "variables": {"input": {\n            "north": bbox[0], "south": bbox[1],\n            "east": bbox[2], "west": bbox[3],\n            "zoom": zoom, "layerSlugs": config.GRAPHQL_LAYERS,\n            "nonClusterableUris": ["dashboard"],\n        }},\n    }\n    r = session.post(config.GRAPHQL_URL, json=payload, timeout=20)\n    r.raise_for_status()\n    data = r.json()\n    if data.get("errors"):\n        raise RuntimeError(str(data["errors"])[:200])\n    q = (data.get("data") or {}).get("mapFeaturesQuery") or {}\n    if q.get("error"):\n        raise RuntimeError(str(q["error"])[:200])\n    return q.get("mapFeatures") or []\n\n\ndef _fetch_incidents_graphql():\n    """Statewide incident list from the 511in.org public-map GraphQL API.\n    Anonymous request (the same data the public map shows). Clusters are\n    drilled into recursively via their bbox/maxZoom."""\n    session = requests.Session()\n    session.headers.update({\n        "User-Agent": "Mozilla/5.0",\n        "Origin": "https://511in.org",\n        "Referer": "https://511in.org/",\n        "language": "en",\n    })\n    events, seen = [], set()\n    budget = [config.GRAPHQL_MAX_REQUESTS]\n\n    def visit(bbox, zoom):\n        if budget[0] <= 0:\n            return\n        budget[0] -= 1\n        for mf in _graphql_map_features(session, bbox, zoom):\n            if mf.get("__typename") == "Cluster":\n                cb = mf.get("bbox")\n                try:\n                    nz = min(int(mf.get("maxZoom") or zoom + 2) + 1, 15)\n                except (TypeError, ValueError):\n                    nz = min(zoom + 2, 15)\n                if cb and nz > zoom:\n                    visit(_norm_bbox(cb), nz)\n                continue\n            uri = mf.get("uri") or ""\n            if uri and uri in seen:\n                continue\n            seen.add(uri)\n            pt = _feature_point(mf)\n            if pt is None:\n                continue\n            tooltip = str(mf.get("tooltip") or "")\n            title = str(mf.get("title") or "event")\n            cat, w = classify_event(title + " " + tooltip)\n            if w <= 0:\n                continue  # e.g. "road back open" — not a risk signal\n            events.append({\n                "id": uri or None,\n                "lat": pt[0], "lon": pt[1],\n                "type": title[:80],\n                "desc": tooltip[:160],\n                "category": cat, "weight": w,\n                "severity": None,\n                "full_closure": "closed" in tooltip.lower(),\n            })\n\n    visit((config.STATE_BBOX["north"], config.STATE_BBOX["south"],\n           config.STATE_BBOX["east"], config.STATE_BBOX["west"]), 11)\n    return events\n\n\ndef _fetch_incidents_legacy():\n    """Old IBI-style JSON endpoints, kept as a fallback."""\n    for url in config.TRAFFICWISE_EVENTS_URLS:\n        if config.TRAFFICWISE_API_KEY and "api/v2" in url:\n            url += "&key=" + config.TRAFFICWISE_API_KEY\n        try:\n            r = requests.get(url, timeout=20,\n                             headers={"User-Agent": "Mozilla/5.0"})\n            r.raise_for_status()\n            raw = r.json()\n            items = raw if isinstance(raw, list) else raw.get("events", [])\n        except Exception as e:  # noqa: BLE001\n            print(f"[warn] legacy event feed failed: {url.split(\'?\')[0]} "\n                  f"({e})", file=sys.stderr)\n            continue\n        events = []\n        for ev in items:\n            lat = ev.get("latitude") or ev.get("lat") or ev.get("Latitude")\n            lon = ev.get("longitude") or ev.get("lon") or ev.get("Longitude")\n            if lat is None or lon is None:\n                continue\n            etype = str(ev.get("type") or ev.get("EventType") or "event")\n            sub = ev.get("Subtype") or ev.get("EventSubType") or ""\n            desc = str(ev.get("Description") or "")[:160]\n            cat, w = classify_event(f"{etype} {sub} {desc}")\n            if w <= 0:\n                continue\n            events.append({\n                "id": ev.get("id") or ev.get("ID"),\n                "lat": float(lat), "lon": float(lon),\n                "type": f"{etype} {sub}".strip(),\n                "desc": desc, "category": cat, "weight": w,\n                "severity": ev.get("Severity"),\n                "full_closure": bool(ev.get("IsFullClosure")),\n            })\n        return events\n    return None\n\n\n# TomTom iconCategory -> (category, weight). Weather-condition warnings\n# (fog / rain / wind) are weighted 0.0 because the weather multiplier\n# already models conditions — counting them again would double-dip.\nTOMTOM_ICON_CATEGORIES = {\n    1: ("crash", 1.0),\n    3: ("closure/hazard", 0.6), 5: ("closure/hazard", 0.6),\n    8: ("closure/hazard", 0.6), 11: ("closure/hazard", 0.6),\n    14: ("stalled/disabled", 0.4),\n    6: ("congestion", 0.3),\n    7: ("roadwork", 0.15), 9: ("roadwork", 0.15),\n    2: ("weather-warning", 0.0), 4: ("weather-warning", 0.0),\n    10: ("weather-warning", 0.0),\n}\n\n_TOMTOM_FIELDS = ("{incidents{type,geometry{type,coordinates},properties{"\n                  "id,iconCategory,magnitudeOfDelay,roadNumbers,"\n                  "events{description,iconCategory}}}}")\n\n\ndef _tomtom_point(geom):\n    """First (lat, lon) from a TomTom incident geometry (Point or\n    LineString; coordinates are [lon, lat])."""\n    c = (geom or {}).get("coordinates")\n    if not c:\n        return None\n    t = (geom or {}).get("type")\n    if t == "Point":\n        return (float(c[1]), float(c[0]))\n    if t in ("LineString", "MultiPoint"):\n        return (float(c[0][1]), float(c[0][0]))\n    if t == "MultiLineString":\n        return (float(c[0][0][1]), float(c[0][0][0]))\n    return None\n\n\ndef _fetch_incidents_tomtom(poly_index=None) -> list[dict]:\n    """Statewide incidents from the TomTom Traffic Incident Details API\n    (v5). The API caps each request\'s bbox at ~10,000 km^2, so the state\n    bbox is tiled with the FEWEST tiles that fit under the cap (16 for\n    Indiana vs 20 with a naive 1-degree grid), and tiles that don\'t\n    overlap any Indiana county are skipped. Returns [] when\n    TOMTOM_API_KEY is not set."""\n    key = os.environ.get("TOMTOM_API_KEY", "").strip()\n    if not key:\n        print("[info] TOMTOM_API_KEY not set; skipping TomTom feed")\n        return []\n    b = config.STATE_BBOX\n    span_lat = b["north"] - b["south"]\n    span_lon = b["east"] - b["west"]\n    lat_km = 111.0\n    # worst case: longitude degrees are widest at the SOUTHERN edge, so\n    # size tiles for that row and every row stays under the area cap\n    lon_km = 111.0 * math.cos(math.radians(b["south"]))\n    rows, cols = 5, 4  # safe fallback\n    for total in range(1, 65):\n        # tile area depends only on the tile count; pick the squarest\n        # rows x cols split so tiles skip out-of-state area effectively\n        km2 = (span_lat * lat_km) * (span_lon * lon_km) / total\n        if km2 > config.TOMTOM_TILE_MAX_KM2:\n            continue\n        splits = [(r_, total // r_) for r_ in range(1, total + 1)\n                  if total % r_ == 0]\n        rows, cols = min(splits, key=lambda rc: abs(\n            span_lat / rc[0] * lat_km - span_lon / rc[1] * lon_km))\n        break\n    step_lat, step_lon = span_lat / rows, span_lon / cols\n    tiles = []\n    for i in range(rows):\n        for j in range(cols):\n            s_ = b["south"] + i * step_lat\n            w_ = b["west"] + j * step_lon\n            n_, e_ = s_ + step_lat, w_ + step_lon\n            if poly_index and not any(\n                    cs <= n_ and cn >= s_ and cw <= e_ and ce >= w_\n                    for _nm, (cs, cn, cw, ce), _gm in poly_index):\n                continue  # tile entirely outside Indiana counties\n            tiles.append((s_, w_, n_, e_))\n    events, seen, tile_fails = [], set(), 0\n    for (s_, w_, n_, e_) in tiles[:config.TOMTOM_MAX_REQUESTS]:\n        params = {\n            "key": key,\n            "bbox": f"{w_},{s_},{e_},{n_}",  # minLon,minLat,maxLon,maxLat\n            "fields": _TOMTOM_FIELDS,\n            "language": "en-US",\n            "timeValidityFilter": "present",\n        }\n        try:\n            r = requests.get(config.TOMTOM_URL, params=params, timeout=20)\n            r.raise_for_status()\n            incidents = r.json().get("incidents") or []\n        except Exception as ex:  # noqa: BLE001\n            tile_fails += 1\n            print(f"[warn] tomtom tile ({s_:.1f},{w_:.1f}) failed: {ex}",\n                  file=sys.stderr)\n            continue\n        for inc in incidents:\n            p = inc.get("properties") or {}\n            iid = p.get("id")\n            if iid and iid in seen:\n                continue  # incidents can straddle tile edges\n            if iid:\n                seen.add(iid)\n            pt = _tomtom_point(inc.get("geometry"))\n            if pt is None:\n                continue\n            descs = [str(ev.get("description") or "")\n                     for ev in (p.get("events") or [])]\n            desc = "; ".join(d for d in descs if d)\n            icon = p.get("iconCategory")\n            if icon in TOMTOM_ICON_CATEGORIES:\n                cat, w = TOMTOM_ICON_CATEGORIES[icon]\n            else:  # unknown icon -> fall back to text classification\n                cat, w = classify_event(desc)\n            if w <= 0:\n                continue  # weather warnings etc.\n            roads = "/".join(p.get("roadNumbers") or [])\n            title = (desc.split(";")[0].strip().capitalize() or cat)\n            if roads:\n                title += f" on {roads}"\n            events.append({\n                "id": iid,\n                "lat": pt[0], "lon": pt[1],\n                "type": title[:80],\n                "desc": (desc or title)[:160],\n                "category": cat, "weight": w,\n                "severity": p.get("magnitudeOfDelay"),\n                "full_closure": icon == 8,\n                "src": "tomtom",\n            })\n    if tile_fails and not events:\n        raise RuntimeError(f"all TomTom tiles failed ({tile_fails})")\n    return events\n\ndef _norm_name(s: str) -> str:\n    import re\n    return re.sub(r"[^a-z]", "", str(s).lower())\n\n\ndef _point_in_ring(lat, lon, ring) -> bool:\n    """Ray-cast point-in-polygon. ring = [[lon, lat], ...]."""\n    inside = False\n    j = len(ring) - 1\n    for i in range(len(ring)):\n        xi, yi = ring[i][0], ring[i][1]\n        xj, yj = ring[j][0], ring[j][1]\n        if ((yi > lat) != (yj > lat)) and (\n                lon < (xj - xi) * (lat - yi) / (yj - yi) + xi):\n            inside = not inside\n        j = i\n    return inside\n\n\ndef _point_in_geom(lat, lon, geom) -> bool:\n    polys = ([geom["coordinates"]] if geom["type"] == "Polygon"\n             else geom["coordinates"])\n    for poly in polys:  # poly[0] = outer ring, rest = holes\n        if _point_in_ring(lat, lon, poly[0]):\n            if any(_point_in_ring(lat, lon, hole) for hole in poly[1:]):\n                continue\n            return True\n    return False\n\n\ndef _county_polygon_index(geodata, county_names):\n    """[(name, bbox, geometry)] for exact event->county assignment.\n    Names are canonicalized to the opportunity table\'s spelling (e.g.\n    Census "LaPorte" -> CSV "Laporte") so risk boosts join correctly."""\n    if not geodata:\n        return None\n    canon = {_norm_name(n): n for n in (county_names or [])}\n    index = []\n    for f in geodata.get("features", []):\n        name = f.get("properties", {}).get("NAME") or f.get("id")\n        name = canon.get(_norm_name(name), name)\n        geom = f.get("geometry") or {}\n        pts = []\n        polys = ([geom["coordinates"]] if geom.get("type") == "Polygon"\n                 else geom.get("coordinates") or [])\n        for poly in polys:\n            pts.extend(poly[0])\n        if not pts:\n            continue\n        lons = [p[0] for p in pts]\n        lats = [p[1] for p in pts]\n        index.append((name, (min(lats), max(lats), min(lons), max(lons)),\n                      geom))\n    return index or None\n\n\ndef _assign_county(lat, lon, poly_index) -> str | None:\n    for name, (s, n, w, e), geom in poly_index:\n        if s <= lat <= n and w <= lon <= e and _point_in_geom(lat, lon,\n                                                              geom):\n            return name\n    return None\n\n\ndef fetch_incidents(geodata=None, county_names=None,\n                    include_tomtom=True,\n                    tomtom_cache=None) -> tuple[pd.Series, list[dict]]:\n    """(county -> weighted activity, event-level list). Events are\n    assigned to the county whose polygon contains them (all 92 counties;\n    out-of-state events from the bbox overhang into Chicago/Louisville/\n    Cincinnati are dropped exactly). If county boundaries are unavailable,\n    falls back to the old nearest-dynamic-centroid-within-35km rule.\n    Primary sources: 511in.org GraphQL (INDOT-managed roads; legacy JSON\n    endpoints as fallback) blended with TomTom probe-data incidents (adds\n    local roads). TomTom events within TOMTOM_DEDUP_KM of a 511 event are\n    dropped so nothing is double-counted.\n\n    tomtom_cache: optional mutable dict persisted by the caller (stored\n    under "_tomtom" in incident_history.json). While the cached snapshot\n    is younger than the day/night refresh threshold it is reused instead\n    of spending API requests; on fetch failure it is the fallback."""\n    poly_index = _county_polygon_index(geodata, county_names)\n    counts = ({n: 0 for n in county_names} if poly_index and county_names\n              else {n: 0 for n in config.COUNTY_CENTROIDS})\n    raw = None\n    try:\n        raw = _fetch_incidents_graphql()\n        print(f"[info] 511 incident feed OK (graphql): "\n              f"{len(raw)} event(s) statewide")\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] 511 graphql feed failed: {e}", file=sys.stderr)\n    if raw is None:\n        raw = _fetch_incidents_legacy()\n    if raw is None:\n        print("[warn] incident feed unavailable: all event feeds failed",\n              file=sys.stderr)\n        raw = []\n    # --- TomTom blend (local-road coverage) --------------------------------\n    tomtom = []\n    if include_tomtom:\n        cache = tomtom_cache if isinstance(tomtom_cache, dict) else {}\n        now = dt.datetime.now()\n        thresh = (config.TOMTOM_REFRESH_DAY_MIN if 6 <= now.hour < 22\n                  else config.TOMTOM_REFRESH_NIGHT_MIN)\n        age_min = None\n        if cache.get("fetched_at"):\n            try:\n                age_min = (now - dt.datetime.fromisoformat(\n                    cache["fetched_at"])).total_seconds() / 60\n            except ValueError:\n                pass\n        if age_min is not None and 0 <= age_min < thresh:\n            tomtom = cache.get("events") or []\n            print(f"[info] tomtom snapshot reused ({age_min:.0f} min old; "\n                  f"refresh threshold {thresh} min) — no API requests spent")\n        else:\n            try:\n                tomtom = _fetch_incidents_tomtom(poly_index)\n                cache["fetched_at"] = now.isoformat(timespec="seconds")\n                cache["events"] = tomtom\n            except Exception as e:  # noqa: BLE001\n                tomtom = cache.get("events") or []\n                print(f"[warn] tomtom incident feed failed: {e}"\n                      + (f" — reusing {age_min:.0f} min old snapshot"\n                         if tomtom and age_min is not None else ""),\n                      file=sys.stderr)\n    if tomtom:\n        deg = config.TOMTOM_DEDUP_KM / 111.0\n        kept = [tv for tv in tomtom\n                if not any(abs(tv["lat"] - ev["lat"]) < deg\n                           and abs(tv["lon"] - ev["lon"]) < deg\n                           for ev in raw)]\n        print(f"[info] tomtom incident feed OK: {len(tomtom)} event(s) "\n              f"statewide, {len(kept)} kept after 511 de-dup")\n        raw = raw + kept\n    events: list[dict] = []\n    for ev in raw:\n        if poly_index:  # exact assignment, all 92 counties\n            best = _assign_county(ev["lat"], ev["lon"], poly_index)\n        else:  # fallback: nearest dynamic centroid within ~35 km\n            best, bd = None, 0.35\n            for name, (cla, clo) in config.COUNTY_CENTROIDS.items():\n                d = math.hypot(ev["lat"] - cla, ev["lon"] - clo)\n                if d < bd:\n                    best, bd = name, d\n        if best:\n            counts.setdefault(best, 0)\n            counts[best] += ev.get("weight", 0.3)  # severity-weighted\n            events.append({**ev, "county": best})\n    if raw:\n        cats: dict[str, int] = {}\n        for ev in events:\n            c = ev.get("category", "other")\n            cats[c] = cats.get(c, 0) + 1\n        breakdown = ", ".join(f"{v} {k}" for k, v in\n                              sorted(cats.items(), key=lambda x: -x[1]))\n        scope = ("Indiana counties (statewide polygons)" if poly_index\n                 else "dynamic counties (centroid fallback)")\n        print(f"[info] {len(events)} of {len(raw)} event(s) mapped to "\n              f"{scope} ({breakdown or \'none\'})")\n    return pd.Series(counts), events\n'
_FILES['memory.py'] = '"""\nTrailing-incident memory.\n\nEvery run logs the live 511 events it observes. Events that have dropped\noff the live feed become "trailing": their importance decays as\n\n    importance = magnitude * 0.5 ** (hours_since_last_seen / HALF_LIFE_H)\n\nso a magnitude-5 pileup from 3 days ago still registers (~0.35 of its\noriginal weight at the default 48 h half-life) while minor events fade\nfast. Trailing weight boosts county risk at half the per-point strength\nof a live event and is drawn on the map as fading markers.\n\nPersistence: JSON file. In Colab, mount Google Drive to keep memory\nacross sessions; otherwise memory covers the current session only.\n"""\nfrom __future__ import annotations\n\nimport datetime as dt\nimport hashlib\nimport json\nimport os\n\nimport config\n\nMAGNITUDE_KEYWORDS = [\n    ("pileup", 5), ("multi vehicle", 5), ("multi-vehicle", 5),\n    ("closed", 4), ("closure", 4), ("hazmat", 4), ("spill", 4),\n    ("overturned", 4), ("jackknif", 4),\n    ("crash", 3), ("accident", 3), ("collision", 3),\n    ("lane blocked", 2), ("lane closed", 2), ("restriction", 2),\n    ("stalled", 1), ("disabled", 1), ("construction", 1),\n]\nDEFAULT_MAGNITUDE = 2\n\n\ndef magnitude_of(event_type: str, desc: str = "", severity=None,\n                 full_closure: bool = False) -> int:\n    t = f"{event_type} {desc}".lower()\n    mag = DEFAULT_MAGNITUDE\n    for kw, m in MAGNITUDE_KEYWORDS:\n        if kw in t:\n            mag = m\n            break\n    if full_closure:\n        mag = max(mag, 4)\n    try:  # Castle Rock Severity is often "1".."5"\n        mag = max(mag, min(int(severity), 5))\n    except (TypeError, ValueError):\n        pass\n    return mag\n\n\ndef event_id(ev: dict) -> str:\n    raw = ev.get("id") or f\'{ev.get("lat"):.3f}|{ev.get("lon"):.3f}|\' \\\n                          f\'{ev.get("type", "")}\'\n    return hashlib.md5(str(raw).encode()).hexdigest()[:12]\n\n\ndef history_path() -> str:\n    envp = os.environ.get("HISTORY_PATH")\n    if envp:\n        return envp\n    drive = "/content/drive/MyDrive/accident_forecaster"\n    if os.path.isdir("/content/drive/MyDrive"):\n        os.makedirs(drive, exist_ok=True)\n        return f"{drive}/incident_history.json"\n    return "incident_history.json"\n\n\ndef load() -> dict:\n    """Local history, merged with the machine-built archive from the\n    GitHub Actions poller when config.INCIDENT_LOG_URL is set. The remote\n    archive wins for events it knows about (its last_seen is fresher)."""\n    hist = {}\n    try:\n        with open(history_path()) as f:\n            hist = json.load(f)\n    except Exception:  # noqa: BLE001\n        pass\n    if config.INCIDENT_LOG_URL:\n        try:\n            import requests\n            remote = requests.get(config.INCIDENT_LOG_URL, timeout=30).json()\n            for eid, e in remote.items():\n                if eid.startswith("_"):  # reserved: ledger, tomtom cache\n                    hist.setdefault(eid, e)\n                    continue\n                if (eid not in hist\n                        or e["last_seen"] >= hist[eid]["last_seen"]):\n                    hist[eid] = e\n            print(f"[info] merged {len(remote)} events from remote archive")\n        except Exception as e:  # noqa: BLE001\n            print(f"[warn] remote incident archive unavailable: {e}")\n    return hist\n\n\ndef save(hist: dict) -> None:\n    with open(history_path(), "w") as f:\n        json.dump(hist, f)\n\n\ndef update(hist: dict, live_events: list[dict],\n           now: dt.datetime | None = None) -> dict:\n    """Merge this run\'s live events into history; prune fully-faded ones."""\n    now = now or dt.datetime.now()\n    now_s = now.isoformat(timespec="seconds")\n    live_ids = set()\n    for ev in live_events:\n        if ev.get("weight", 1.0) < config.MEMORY_MIN_WEIGHT:\n            continue  # roadwork/congestion: no trailing value, bloats file\n        eid = event_id(ev)\n        live_ids.add(eid)\n        if eid in hist:\n            hist[eid]["last_seen"] = now_s\n        else:\n            hist[eid] = {\n                "first_seen": now_s, "last_seen": now_s,\n                "lat": ev.get("lat"), "lon": ev.get("lon"),\n                "county": ev.get("county"), "type": ev.get("type", "event"),\n                "desc": ev.get("desc", ""),\n                "category": ev.get("category", ""),\n                "magnitude": magnitude_of(ev.get("type", ""),\n                                          ev.get("desc", ""),\n                                          ev.get("severity"),\n                                          ev.get("full_closure", False)),\n            }\n    # prune events decayed below 5% of a magnitude-1 event\n    keep = {}\n    for eid, e in hist.items():\n        if eid.startswith("_"):\n            keep[eid] = e  # reserved keys (e.g. the crash ledger)\n            continue\n        if eid in live_ids or _decay(e, now) * e["magnitude"] >= 0.05:\n            keep[eid] = e\n    return keep\n\n\ndef _decay(e: dict, now: dt.datetime) -> float:\n    last = dt.datetime.fromisoformat(e["last_seen"])\n    hours = max((now - last).total_seconds() / 3600, 0)\n    return 0.5 ** (hours / config.TRAILING_HALF_LIFE_H)\n\n\ndef trailing(hist: dict, live_ids: set[str],\n             now: dt.datetime | None = None) -> list[dict]:\n    """Decayed non-live events: [{lat, lon, county, type, magnitude,\n    importance, age_h}] with importance = magnitude * decay."""\n    now = now or dt.datetime.now()\n    out = []\n    for eid, e in hist.items():\n        if eid in live_ids or eid.startswith("_"):\n            continue\n        d = _decay(e, now)\n        imp = e["magnitude"] * d\n        if imp < 0.05:\n            continue\n        age_h = (now - dt.datetime.fromisoformat(e["last_seen"])\n                 ).total_seconds() / 3600\n        out.append({**e, "importance": round(imp, 3),\n                    "decay": round(d, 3), "age_h": round(age_h, 1)})\n    return sorted(out, key=lambda x: -x["importance"])\n\n\ndef county_trailing_scores(trail: list[dict]) -> dict[str, float]:\n    scores: dict[str, float] = {}\n    for e in trail:\n        c = e.get("county")\n        if c:\n            scores[c] = scores.get(c, 0.0) + e["importance"]\n    return scores\n'
_FILES['model.py'] = '"""\nCounty risk model (v2).\n\nrisk(county, hour) = opportunity(county) × exposure(hour-of-week)\n                     × weather_multiplier(county, hour)\ncounty_score       = Σ_hours risk × incident_boost(county)\n\nStatic-tier counties (outside the top DYNAMIC_N) use neutral weather, so\ntheir score is pure baseline — they can\'t gain from conditions but remain\nin the allocation.\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nimport config\nfrom sources import weather_multiplier\n\n\ndef hourly_exposure() -> np.ndarray:\n    vec = []\n    for wd in range(7):\n        prof = config.WEEKDAY_HOURLY if wd < 5 else config.WEEKEND_HOURLY\n        vec.extend(prof)\n    v = np.array(vec, dtype=float)\n    return v / v.mean()\n\n\ndef score(counties: pd.DataFrame,\n          weather: dict[str, pd.DataFrame],\n          incidents: pd.Series,\n          hours: int = 48,\n          trailing_scores: dict[str, float] | None = None,\n          ledger_factors: dict[str, float] | None = None\n          ) -> tuple[pd.DataFrame, pd.DataFrame]:\n    """Returns (county_scores, county_hourly)."""\n    exposure = hourly_exposure()\n    hourly_rows = []\n    horizon, drivers = {}, {}\n    for _, c in counties.iterrows():\n        name = c["county"]\n        wdf = weather.get(name)\n        if c["dynamic"] and wdf is not None:\n            total = 0.0\n            cond_hours: dict[str, int] = {}\n            peak_ts, peak_risk = None, -1.0\n            for ts, row in wdf.iloc[:hours].iterrows():\n                wm = weather_multiplier(row)\n                ex = float(exposure[ts.weekday() * 24 + ts.hour])\n                risk = wm * ex\n                total += risk\n                lab = condition_label(row)\n                if lab:\n                    cond_hours[lab] = cond_hours.get(lab, 0) + 1\n                if risk > peak_risk:\n                    peak_risk, peak_ts = risk, ts\n                hourly_rows.append({\n                    "county": name, "time": ts,\n                    "weather_mult": round(wm, 3), "exposure": round(ex, 3),\n                    "hour_risk": round(risk, 3),\n                })\n            horizon[name] = total\n            cond_txt = ", ".join(f"{v}h {k}" for k, v in sorted(\n                cond_hours.items(), key=lambda x: -x[1])) or "clear/dry"\n            drivers[name] = {\n                "conditions": cond_txt,\n                "peak": peak_ts.strftime("%a %H:00") if peak_ts is not None\n                        else "",\n            }\n        else:\n            horizon[name] = float(hours)  # neutral: mean multiplier 1.0\n\n    out = counties.copy()\n    out["horizon_weather"] = out["county"].map(horizon)\n    out["wx_conditions"] = out["county"].map(\n        lambda n: drivers.get(n, {}).get("conditions", "static tier"))\n    out["wx_peak"] = out["county"].map(\n        lambda n: drivers.get(n, {}).get("peak", ""))\n    out["weather_lift"] = (out["horizon_weather"] / hours).round(3)\n    ev = out["county"].map(incidents).fillna(0)\n    out["active_events"] = ev.round(2)  # severity-weighted activity\n    tr = out["county"].map(trailing_scores or {}).fillna(0.0)\n    out["trailing_weight"] = tr.round(2)\n    out["incident_boost"] = np.minimum(\n        1 + config.INCIDENT_BOOST_PER_EVENT * ev\n        + config.TRAILING_BOOST_PER_POINT * tr,\n        config.INCIDENT_BOOST_CAP)\n    lf = out["county"].map(ledger_factors or {}).fillna(1.0)\n    out["learned_adj"] = lf.round(3)  # long-term crash-ledger factor\n    out["risk_score"] = (out["opportunity_score"] * out["horizon_weather"]\n                         * out["incident_boost"] * lf)\n    out["risk_score"] = (100 * out["risk_score"]\n                         / out["risk_score"].max()).round(2)\n    out = out.sort_values("risk_score", ascending=False)\n    return out, pd.DataFrame(hourly_rows)\n\n\ndef condition_label(row) -> str | None:\n    """Human label for the dominant adverse condition in a forecast hour."""\n    rain = row.get("precipitation", 0.0)\n    snow = row.get("snowfall", 0.0)\n    if row.get("freezing_precip_flag", False) or (\n            rain > 0.1 and row.get("temperature_2m", 15) <= 0):\n        return "freezing rain/ice"\n    if snow > 1.0:\n        return "heavy snow"\n    if snow > 0.1:\n        return "snow"\n    if rain > 2.5:\n        return "heavy rain"\n    if rain > 0.1:\n        return "rain"\n    if row.get("visibility", 20000) < 1000:\n        return "fog"\n    return None\n'
_FILES['geo.py'] = '"""\nGeometry + commuter-flow data (fetched live in Colab; graceful fallbacks).\n\n- Indiana county polygons: Census/plotly counties GeoJSON, filtered to\n  STATE == "18". Gives real boundaries for the choropleth and centroids\n  computed from the polygons (replacing hand-entered centroids for flows).\n- Commuter origins: Census LODES8 origin-destination files for Indiana\n  (block-level home->work job counts, aggregated to county). The inbound\n  commuter mix of a county is the best public proxy for "where the people\n  driving through it come from." main = both ends in Indiana; aux adds\n  out-of-state residents working in Indiana (rolled up to state level).\n"""\nfrom __future__ import annotations\n\nimport re\nimport sys\n\nimport pandas as pd\nimport requests\n\nGEOJSON_URL = ("https://raw.githubusercontent.com/plotly/datasets/master/"\n               "geojson-counties-fips.json")\nLODES_MAIN = ("https://lehd.ces.census.gov/data/lodes/LODES8/in/od/"\n              "in_od_main_JT00_2022.csv.gz")\nLODES_AUX = ("https://lehd.ces.census.gov/data/lodes/LODES8/in/od/"\n             "in_od_aux_JT00_2022.csv.gz")\n\nNEIGHBOR_STATES = {  # state FIPS -> (label, approx centroid) for flow lines\n    "17": ("Illinois", (40.0, -89.2)), "21": ("Kentucky", (37.5, -85.3)),\n    "39": ("Ohio", (40.3, -82.8)), "26": ("Michigan", (43.3, -84.6)),\n}\nSTATE_NAMES = {"17": "Illinois", "21": "Kentucky", "39": "Ohio",\n               "26": "Michigan", "state": "out of state"}\n\n\ndef _norm(s: str) -> str:\n    return re.sub(r"[^a-z]", "", str(s).lower())\n\n\ndef fetch_indiana_geojson() -> dict | None:\n    """{\'features\': [...], \'fips_to_name\': {}, \'name_to_fips\': {},\n        \'centroids\': {fips: (lat, lon)}} or None if unreachable."""\n    try:\n        gj = requests.get(GEOJSON_URL, timeout=90).json()\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] county GeoJSON unavailable ({e}); map falls back "\n              "to geographic circles.", file=sys.stderr)\n        return None\n    feats = [f for f in gj["features"]\n             if f.get("properties", {}).get("STATE") == "18"]\n    fips_to_name, centroids = {}, {}\n    for f in feats:\n        fips = f.get("id") or ("18" + f["properties"]["COUNTY"])\n        f["id"] = fips\n        name = f["properties"].get("NAME", fips)\n        fips_to_name[fips] = name\n        centroids[fips] = _centroid(f["geometry"])\n    return {"features": feats, "fips_to_name": fips_to_name,\n            "name_to_fips": {_norm(v): k for k, v in fips_to_name.items()},\n            "centroids": centroids}\n\n\ndef _centroid(geom: dict) -> tuple[float, float]:\n    if geom["type"] == "Polygon":\n        ring = geom["coordinates"][0]\n    else:  # MultiPolygon: use largest ring\n        ring = max((p[0] for p in geom["coordinates"]), key=len)\n    lon = sum(p[0] for p in ring) / len(ring)\n    lat = sum(p[1] for p in ring) / len(ring)\n    return (round(lat, 4), round(lon, 4))\n\n\ndef fetch_flows() -> pd.DataFrame | None:\n    """County-level OD: columns w_cty (workplace FIPS, all 18xxx),\n    h_cty (home FIPS, any state), jobs. None if unreachable."""\n    frames = []\n    for url in (LODES_MAIN, LODES_AUX):\n        try:\n            df = pd.read_csv(url, usecols=["w_geocode", "h_geocode", "S000"],\n                             dtype={"w_geocode": str, "h_geocode": str})\n            frames.append(df)\n        except Exception as e:  # noqa: BLE001\n            print(f"[warn] LODES fetch failed for {url.split(\'/\')[-1]} "\n                  f"({e})", file=sys.stderr)\n    if not frames:\n        return None\n    od = pd.concat(frames, ignore_index=True)\n    od["w_cty"] = od["w_geocode"].str[:5]\n    od["h_cty"] = od["h_geocode"].str[:5]\n    return (od.groupby(["w_cty", "h_cty"])["S000"].sum()\n            .rename("jobs").reset_index())\n\n\ndef top_origins(flows: pd.DataFrame | None, geo: dict | None,\n                k: int = 6) -> dict:\n    """{workplace_fips: [{label, share, lat, lon(or None)}...]} — the top\n    inbound commuter origins for every Indiana county."""\n    if flows is None:\n        return {}\n    fips_to_name = geo["fips_to_name"] if geo else {}\n    centroids = geo["centroids"] if geo else {}\n    out = {}\n    for w, grp in flows.groupby("w_cty"):\n        total = grp["jobs"].sum()\n        ext = grp[grp["h_cty"] != w].copy()\n        # roll out-of-state homes up to state level\n        ext["origin"] = ext["h_cty"].where(\n            ext["h_cty"].str.startswith("18"), "S" + ext["h_cty"].str[:2])\n        agg = (ext.groupby("origin")["jobs"].sum()\n               .sort_values(ascending=False).head(k))\n        rows = []\n        for origin, jobs in agg.items():\n            if origin.startswith("S"):\n                sf = origin[1:]\n                label, cen = NEIGHBOR_STATES.get(\n                    sf, (STATE_NAMES.get(sf, f"state {sf}"), None))\n            else:\n                label = fips_to_name.get(origin, origin) + " Co."\n                cen = centroids.get(origin)\n            rows.append({\n                "label": label, "share": round(float(jobs / total), 3),\n                "lat": cen[0] if cen else None,\n                "lon": cen[1] if cen else None,\n            })\n        internal = float(grp[grp["h_cty"] == w]["jobs"].sum() / total)\n        out[w] = {"origins": rows, "internal_share": round(internal, 3)}\n    return out\n'
_FILES['mapbuild.py'] = '"""\nInteractive risk map (v4).\n\nCollisions vs contributing factors: only actual crashes get map markers —\nlive ⚠ plus recent 💥 crashes from trailing memory, which fade over ~2\ndays (the caller passes trail pre-filtered to crashes).\nEverything else — weather, recent-incident echo, closures/roadwork/\ncongestion — shapes the county COLOR, and the county click-panel itemizes\nexactly what fed it. Alongside the HTML, build_map writes\nlive_markers.json; the open page re-fetches it (same-origin, no keys)\nevery 5 minutes so markers and colors track the newest pipeline run\nwithout a manual reload.\n\n- County polygons (choropleth) shaded by risk — geometry is geographic, so\n  it stays county-sized at every zoom level. Fallback when the GeoJSON\n  can\'t be fetched: L.circle with a radius in *meters* (also zoom-correct).\n- Hover tooltip explains WHY a county is hot: EMS opportunity rank and\n  injured patients/yr, weather conditions in the horizon and the peak-risk\n  window, active incidents, and the county\'s top inbound commuter origins.\n- Click a county to draw its commuter inflow lines (Census LODES): where\n  the people traveling through it come from, line weight ~ share.\n- LIVE MODE: while the page is open it re-fetches Open-Meteo every 15\n  minutes for the dynamic counties, recomputes the weather multipliers in\n  the browser, and recolors the map. Incidents refresh on notebook re-run.\n"""\nfrom __future__ import annotations\n\nimport datetime as _dt\nimport json\nimport os\n\nimport config\n\n\ndef build_map(scores, geo, origins, *, badges=None, path, hours=48, trail=None,\n              live=None):\n    fips_by_norm = geo["name_to_fips"] if geo else {}\n    import re\n    norm = lambda s: re.sub(r"[^a-z]", "", str(s).lower())  # noqa: E731\n\n    counties_js = {}\n    for r in scores.itertuples():\n        fips = fips_by_norm.get(norm(r.county))\n        cen = (geo["centroids"].get(fips) if geo and fips\n               else config.COUNTY_CENTROIDS.get(r.county))\n        counties_js[r.county] = {\n            "fips": fips, "risk": float(r.risk_score),\n            "rank": int(r.rank), "injured": float(r.injured_patients),\n            "serious": float(r.serious_cases),\n            "opportunity": float(r.opportunity_score),\n            "metro": r.metro, "dynamic": bool(r.dynamic),\n            "events": float(r.active_events),\n            "incBoost": float(r.incident_boost),\n            "lift": float(r.weather_lift),\n            "wx": r.wx_conditions, "peak": r.wx_peak,\n            "trailing": float(r.trailing_weight),\n            "learned": float(getattr(r, "learned_adj", 1.0)),\n            "truckBadge": (badges or {}).get("truck", {}).get(r.county),\n            "rideBadge": (badges or {}).get("ride", {}).get(r.county),\n            "lat": cen[0] if cen else None,\n            "lon": cen[1] if cen else None,\n            "flows": (origins.get(fips, {}) if fips else {}),\n        }\n\n    features = geo["features"] if geo else []\n    generated = _dt.datetime.now().isoformat(timespec="seconds")\n    payload = {\n        "counties": counties_js,\n        "generated": generated,\n        "minMarkerW": config.MAP_MIN_MARKER_WEIGHT,\n        "trail": [\n            {"lat": e["lat"], "lon": e["lon"], "type": e["type"],\n             "desc": e.get("desc", ""), "county": e["county"],\n             "mag": e["magnitude"], "imp": e["importance"],\n             "decay": e["decay"], "age_h": e["age_h"]}\n            for e in (trail or []) if e.get("lat") is not None],\n        "live": [\n            {"lat": e["lat"], "lon": e["lon"],\n             "type": str(e.get("type", "event"))[:80],\n             "desc": str(e.get("desc", ""))[:160],\n             "cat": e.get("category", "other"),\n             "w": e.get("weight", 0.3),\n             "county": e.get("county", "")}\n            for e in (live or []) if e.get("lat") is not None],\n        "features": features,\n        "hours": hours,\n        "exposure": _exposure_vec(),\n        "dynamicCentroids": {\n            c: {"lat": counties_js[c]["lat"], "lon": counties_js[c]["lon"]}\n            for c, v in counties_js.items()\n            if v["dynamic"] and v["lat"] is not None},\n    }\n\n    html = _TEMPLATE.replace("__PAYLOAD__", json.dumps(payload))\n    with open(path, "w") as f:\n        f.write(html)\n    # Sidecar consumed by the open page\'s 5-minute incident auto-refresh\n    # (same-origin fetch; must be published next to the HTML).\n    refresh = {\n        "generated": generated,\n        "live": payload["live"],\n        "trail": payload["trail"],\n        "counties": {n: {"events": c["events"], "incBoost": c["incBoost"],\n                         "trailing": c["trailing"]}\n                     for n, c in counties_js.items()},\n    }\n    side = os.path.join(os.path.dirname(path) or ".", "live_markers.json")\n    with open(side, "w") as f:\n        json.dump(refresh, f)\n\n\ndef _exposure_vec():\n    vec = []\n    for wd in range(7):\n        prof = config.WEEKDAY_HOURLY if wd < 5 else config.WEEKEND_HOURLY\n        vec.extend(prof)\n    mean = sum(vec) / len(vec)\n    return [round(v / mean, 4) for v in vec]\n\n\n_TEMPLATE = r"""<!DOCTYPE html><html><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Indiana Accident Risk — Live</title>\n<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css"/>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"></script>\n<style>\nhtml,body{height:100%;margin:0;font-family:system-ui,sans-serif}\n#map{height:100%;transition:margin-right .25s}\nbody.panel-open #map{margin-right:360px}\n.panel-box{background:#fff;padding:8px 12px;border-radius:6px;font-size:13px;\nbox-shadow:0 1px 4px rgba(0,0,0,.3)}\n.leaflet-tooltip.hint{font-size:12px;font-weight:600;padding:3px 8px}\n.leaflet-interactive{cursor:pointer}\n#side{position:fixed;top:0;right:-380px;width:360px;height:100%;background:#fff;\nbox-shadow:-2px 0 10px rgba(0,0,0,.25);transition:right .25s;z-index:1200;\noverflow-y:auto;box-sizing:border-box;padding:16px 18px}\nbody.panel-open #side{right:0}\n#side h2{margin:0 44px 4px 0;font-size:18px}\n#side .badge{display:inline-block;padding:1px 9px;border-radius:10px;color:#fff;font-weight:700}\n#side .sec{margin:14px 0 0}\n#side .sec h3{margin:0 0 4px;font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:#777}\n#side .sec div{font-size:13.5px;line-height:1.5}\n#closebtn{position:absolute;top:10px;right:12px;border:none;background:#eee;\nborder-radius:50%;width:28px;height:28px;font-size:15px;cursor:pointer}\n.origin-row{display:flex;justify-content:space-between;border-bottom:1px solid #f0f0f0;padding:2px 0}\n.bar{height:6px;background:#08519c;border-radius:3px;margin-top:2px}\n.inc{display:flex;align-items:center;justify-content:center;border-radius:50%;\nbackground:#fff;font-weight:700;box-shadow:0 1px 6px rgba(0,0,0,.6);\nline-height:1}\n.inc.live{border:3px solid #c62828;color:#c62828}\n.inc.past{border:3px solid #5e35b1;color:#5e35b1}\n@media (max-width:700px){#side{width:85%}body.panel-open #map{margin-right:0}}\n</style></head><body><div id="map"></div>\n<div id="side"><button id="closebtn" onclick="closePanel()">×</button><div id="sidecontent"></div></div>\n<script>\nconst D = __PAYLOAD__;\nconst map = L.map(\'map\').setView([39.9,-86.3],7);\nL.tileLayer(\'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png\',\n {attribution:\'&copy; OpenStreetMap · risk: EMS opportunity × weather × exposure · flows: Census LODES\'}).addTo(map);\n\nconst byFips = {};\nObject.entries(D.counties).forEach(([name,c])=>{ c.name=name; if(c.fips) byFips[c.fips]=c; });\n\n// Continuous, power-scaled ramp: opportunity is very top-heavy, so a\n// linear scale flattens most counties into one shade. t = (r/100)^0.35\n// spreads the low end — risk 1, 3, and 8 get visibly different fills.\nconst RAMP=[[0,[255,243,238]],[0.25,[252,187,161]],[0.5,[251,106,74]],[0.75,[203,24,29]],[1,[103,0,13]]];\nfunction color(r){\n  const t=Math.pow(Math.min(Math.max(r,0),100)/100,0.35);\n  for(let i=1;i<RAMP.length;i++){\n    if(t<=RAMP[i][0]){\n      const [t0,c0]=RAMP[i-1],[t1,c1]=RAMP[i],f=(t-t0)/(t1-t0);\n      return \'rgb(\'+c0.map((v,k)=>Math.round(v+(c1[k]-v)*f)).join(\',\')+\')\';\n    }\n  }\n  return \'rgb(103,0,13)\';\n}\n// Incident heat flush: blend the fill toward hot red in proportion to the\n// county\'s incident boost. One live crash (boost x1.10) is a clearly\n// visible warm shift even on a pale county; it fades back over ~2 days\n// exactly as the trailing weight decays the boost toward x1.00.\nfunction fillFor(c){\n  const k=Math.min(1,Math.max(0,(c.incBoost-1)/0.3));\n  if(k<=0.01) return color(c.risk);\n  const m=color(c.risk).match(/\\d+/g).map(Number);\n  const hot=[225,25,0];\n  const f=0.5*k;\n  return \'rgb(\'+m.map((v,i)=>Math.round(v+(hot[i]-v)*f)).join(\',\')+\')\';\n}\n\n// ---------- side panel ----------\nfunction sec(title, body){ return `<div class="sec"><h3>${title}</h3><div>${body}</div></div>`; }\nfunction panelHTML(c,name){\n  let h = `<h2>${name} County <span class="badge" style="background:${color(c.risk)}">risk ${c.risk.toFixed(1)}</span></h2>`;\n  h += `<div style="color:#777;font-size:12.5px">${c.metro===\'other_in\'?\'outside core metros\':c.metro+\' market\'} · next ${D.hours}h</div>`;\n  h += sec(\'Why this county scores here\',\n    `#${c.rank} statewide in EMS-measured crash injuries — ${Math.round(c.injured).toLocaleString()} injured patients/yr, ${Math.round(c.serious)} serious cases.`);\n  if(c.dynamic){\n    h += sec(\'Weather (next \'+D.hours+\'h)\',\n      `${c.wx}. Overall risk lift <b>×${c.lift.toFixed(2)}</b>${c.peak?`; peak-risk window <b>${c.peak}</b>`:\'\'}.`);\n  } else {\n    h += sec(\'Weather\', \'<i>Weather feed did not reach this county this run — using neutral baseline.</i>\');\n  }\n  let inc=\'\';\n  const f=countyFactors(name), crashes=f[\'crash\']||0;\n  if(crashes) inc += `<b>⚠ ${crashes} active crash${crashes>1?\'es\':\'\'}</b> — marked on the map.<br>`;\n  const parts=Object.entries(f).filter(([k])=>k!==\'crash\')\n    .map(([k,v])=>`${v} ${FACTOR_LABEL[k]||k}`);\n  if(parts.length) inc += `<b>Traffic factors</b> shading this county (no markers): ${parts.join(\', \')}.<br>`;\n  if(c.trailing>0.05) inc += `<b>Recent-incident echo</b>: weight <b>${c.trailing.toFixed(1)}</b> from significant events in the last ~2 days, fading as they age.<br>`;\n  if(inc) inc += `Together these boost this county\'s color ×${c.incBoost.toFixed(2)} on top of its injury baseline and weather.`;\n  h += sec(\'Live & recent traffic (feeds the color)\', inc ||\n    \'Nothing live or recent — color here is injury baseline × weather only.\');\n  if(c.truckBadge || c.rideBadge){\n    let vp=\'\';\n    if(c.truckBadge) vp += `🚛 <b>Trucking-crash-prone</b> — ${c.truckBadge}.<br>`;\n    if(c.rideBadge)  vp += `🚕 <b>Rideshare-crash-prone</b> — ${c.rideBadge}.`;\n    h += sec(\'Vehicle profile\', vp);\n  }\n  if(c.learned && Math.abs(c.learned-1)>=0.005)\n    h += sec(\'Learned county adjustment\', `Official ARIES crash records (all roads, all severities) blended with every crash our own feeds record shift this county ×<b>${c.learned.toFixed(2)}</b> against its EMS-injury baseline (capped and shrunk toward 1.0 — the EMS baseline stays the anchor).`);\n  if(c.flows && c.flows.origins && c.flows.origins.length){\n    let rows = `<div class="origin-row"><span>local (lives in-county)</span><b>${((c.flows.internal_share||0)*100).toFixed(0)}%</b></div>`;\n    const mx = Math.max(...c.flows.origins.map(o=>o.share));\n    c.flows.origins.forEach(o=>{\n      rows += `<div class="origin-row"><span>${o.label}</span><b>${(o.share*100).toFixed(1)}%</b></div>`+\n              `<div class="bar" style="width:${(o.share/mx*100).toFixed(0)}%"></div>`;\n    });\n    rows += `<div style="color:#777;font-size:12px;margin-top:6px">Census commuter data — blue lines on the map show these inflows. Counties above are candidates to include in this hotspot\'s ad geography.</div>`;\n    h += sec(\'Who travels through (origins)\', rows);\n  }\n  return h;\n}\nfunction incidentPanelHTML(t){\n  const age = t.age_h<48 ? `${Math.round(t.age_h)}h ago` : `${(t.age_h/24).toFixed(1)} days ago`;\n  let h = `<h2>💥 Recent crash <span class="badge" style="background:#5e35b1">fading</span></h2>`;\n  h += sec(\'What\', `${t.type}${t.desc?`<br><span style="color:#555">${t.desc}</span>`:\'\'}`);\n  h += sec(\'Where / when\', `${t.county} County · last seen on the live feed ${age}.`);\n  h += sec(\'Current weight\', `Magnitude ${t.mag}/5, decayed to <b>${t.imp.toFixed(2)}</b> (${(t.decay*100).toFixed(0)}% remaining; 48h half-life). It fades from the map as it decays.`);\n  return h;\n}\nconst FACTOR_LABEL={\'closure/hazard\':\'closures/hazards\',\'stalled/disabled\':\'stalled vehicles\',\n \'congestion\':\'congestion reports\',\'roadwork\':\'roadwork zones\',\'other\':\'other events\'};\nfunction countyFactors(name){\n  const f={};(D.live||[]).forEach(t=>{if(t.county===name)f[t.cat]=(f[t.cat]||0)+1;});\n  return f;\n}\nfunction openPanel(html){ document.getElementById(\'sidecontent\').innerHTML=html; document.body.classList.add(\'panel-open\'); setTimeout(()=>map.invalidateSize(),260); }\nfunction closePanel(){ document.body.classList.remove(\'panel-open\'); flowLayer.clearLayers(); setTimeout(()=>map.invalidateSize(),260); }\n\n// ---------- flows ----------\nlet flowLayer = L.layerGroup().addTo(map);\nfunction drawFlows(c){\n  flowLayer.clearLayers();\n  if(!(c.flows&&c.flows.origins&&c.lat)) return;\n  c.flows.origins.forEach(o=>{\n    if(o.lat==null) return;\n    L.polyline([[o.lat,o.lon],[c.lat,c.lon]],{color:\'#08519c\',weight:1+o.share*30,opacity:.65}).addTo(flowLayer);\n    L.circleMarker([o.lat,o.lon],{radius:4,color:\'#08519c\',fillOpacity:.9}).addTo(flowLayer);\n  });\n}\n\n// ---------- county layer ----------\nlet geoLayer=null, fallbackLayer=null;\nfunction styleFor(c){return {color:\'#555\',weight:c.events>0?2.5:1,\n  dashArray:c.events>0?\'4\':null,fillColor:fillFor(c),fillOpacity:.62};}\nconst hoverStyle={weight:3,color:\'#111\',fillOpacity:.8};\n\nfunction wireCounty(layer,c,name){\n  layer.bindTooltip(`${name} County — click for details`,{sticky:true,className:\'hint\',direction:\'top\'});\n  layer.on(\'mouseover\',()=>layer.setStyle(hoverStyle));\n  layer.on(\'mouseout\',()=>layer.setStyle(styleFor(c)));\n  layer.on(\'click\',()=>{openPanel(panelHTML(c,name)); drawFlows(c);});\n}\nfunction render(){\n  if(D.features && D.features.length){\n    if(geoLayer) map.removeLayer(geoLayer);\n    geoLayer = L.geoJSON({type:\'FeatureCollection\',features:D.features},{\n      style: f=>{const c=byFips[f.id]; return c?styleFor(c):{fillColor:\'#eee\',color:\'#999\',weight:.5,fillOpacity:.3};},\n      onEachFeature:(f,layer)=>{ const c=byFips[f.id]; if(c) wireCounty(layer,c,c.name); }}).addTo(map);\n  } else {\n    if(fallbackLayer) map.removeLayer(fallbackLayer);\n    fallbackLayer=L.layerGroup().addTo(map);\n    Object.entries(D.counties).forEach(([name,c])=>{\n      if(c.lat==null) return;\n      const layer=L.circle([c.lat,c.lon],{radius:13000,...styleFor(c)}).addTo(fallbackLayer);\n      wireCounty(layer,c,name);\n    });\n  }\n}\nrender();\n\n// ---------- incident markers (live + fading past) ----------\nfunction incIcon(cls, sym, size, alpha){\n  return L.divIcon({className:\'\', iconSize:[size,size], iconAnchor:[size/2,size/2],\n    html:`<div class="inc ${cls}" style="width:${size}px;height:${size}px;opacity:${alpha};font-size:${Math.round(size*0.62)}px">${sym}</div>`});\n}\nfunction agoTxt(h){ return h<48 ? Math.round(h)+\'h ago\' : (h/24).toFixed(1)+\'d ago\'; }\nfunction livePanelHTML(t){\n  let h = `<h2>⚠ Live incident <span class="badge" style="background:#c62828">active now</span></h2>`;\n  h += sec(\'What\', `${t.type}${t.desc?`<br><span style="color:#555">${t.desc}</span>`:\'\'}`);\n  h += sec(\'Where\', `${t.county} County — currently on the live incident feeds.`);\n  h += sec(\'Risk contribution\', `Classified as <b>${t.cat}</b> — weight ${t.w.toFixed(2)} toward this county\'s color.`);\n  return h;\n}\nconst liveLayer = L.layerGroup().addTo(map);\nfunction drawLive(){\n  liveLayer.clearLayers();\n  (D.live||[]).forEach(t=>{\n    if(t.w < D.minMarkerW) return; // factors shade the county, no marker\n    const m=L.marker([t.lat,t.lon],{icon:incIcon(\'live\',\'⚠\',30,1),zIndexOffset:1000+Math.round(t.w*100)}).addTo(liveLayer);\n    m.bindTooltip(`LIVE ${t.cat}: ${t.type}`,{sticky:true,className:\'hint\',direction:\'top\'});\n    m.on(\'click\',()=>openPanel(livePanelHTML(t)));\n  });\n}\ndrawLive();\nconst trailLayer = L.layerGroup().addTo(map);\nfunction drawTrail(){\n  trailLayer.clearLayers();\n  (D.trail||[]).forEach(t=>{\n    const size=20+t.mag*3, alpha=0.55+0.45*t.decay;\n    const m=L.marker([t.lat,t.lon],{icon:incIcon(\'past\',\'💥\',size,alpha),zIndexOffset:500}).addTo(trailLayer);\n    m.bindTooltip(`Recent crash: ${t.type} — ${agoTxt(t.age_h)}`,{sticky:true,className:\'hint\',direction:\'top\'});\n    m.on(\'click\',()=>openPanel(incidentPanelHTML(t)));\n  });\n}\ndrawTrail();\n// ---------- vehicle-profile county badges ----------\nconst badgeLayer = L.layerGroup().addTo(map);\nObject.entries(D.counties).forEach(([name,c])=>{\n  if(c.lat==null) return;\n  const put=(sym,txt,dx)=>{\n    const m=L.marker([c.lat,c.lon+dx],{icon:L.divIcon({className:\'\',iconSize:[24,24],iconAnchor:[12,12],\n      html:`<div style="width:24px;height:24px;border-radius:6px;background:#fff;border:1.5px solid #444;box-shadow:0 1px 3px rgba(0,0,0,.35);display:flex;align-items:center;justify-content:center;font-size:15px">${sym}</div>`}),\n      zIndexOffset:300}).addTo(badgeLayer);\n    m.bindTooltip(`${name} County — ${txt}`,{sticky:true,className:\'hint\',direction:\'top\'});\n    m.on(\'click\',()=>openPanel(panelHTML(c,name)));\n  };\n  if(c.truckBadge) put(\'🚛\', \'trucking-crash-prone: \'+c.truckBadge, -0.055);\n  if(c.rideBadge)  put(\'🚕\', \'rideshare-crash-prone: \'+c.rideBadge, c.truckBadge?0.055:-0.055);\n});\n\n// ---------- legend + live status ----------\nconst legend=L.control({position:\'bottomright\'});\nlegend.onAdd=()=>{const d=L.DomUtil.create(\'div\',\'panel-box\');\n d.innerHTML=\'<b>County risk (next \'+D.hours+\'h)</b><br>\'+\n \'<span style="background:linear-gradient(90deg,rgb(255,243,238),rgb(252,187,161),rgb(251,106,74),rgb(203,24,29),rgb(103,0,13));display:inline-block;width:130px;height:10px;border:1px solid #999;vertical-align:middle"></span> low → high\'+\n \'<br>red flush = live/recent incidents there (fades as they decay)\'+\n \'<br><span style="color:#c62828">⚠</span> live crash · <span style="color:#5e35b1">💥</span> recent crash (fades ~2 days)\'+\n \'<br>🚛/🚕 truck- / rideshare-crash-prone county\'+\n \'<br>color = injuries baseline × weather × traffic factors\'+\n \'<br>click any county or marker for details\'+\n \'<br><span id="livestatus" style="color:#666">live weather: starting…</span>\'+\n \'<br><span id="incstatus" style="color:#666">incidents: from this build</span>\';\n return d;};\nlegend.addTo(map);\n\n// ---------- LIVE MODE: refresh weather every 15 min ----------\nconst MULT={rl:1.25,rm:1.5,rh:1.8,sl:1.5,sm:1.8,sh:2.2,fz:2.5,fog:1.4,dark:1.25,wind:1.15};\nfunction wmult(p,s,t,vis,g,day,code){\n  let m=1;\n  if([56,57,66,67].includes(code)||(p>0.1&&t<=0)) m*=MULT.fz;\n  else if(s>2.5)m*=MULT.sh; else if(s>1)m*=MULT.sm; else if(s>0.1)m*=MULT.sl;\n  else if(p>7.6)m*=MULT.rh; else if(p>2.5)m*=MULT.rm; else if(p>0.1)m*=MULT.rl;\n  if(vis<1000)m*=MULT.fog; if(!day)m*=MULT.dark; if(g>40)m*=MULT.wind;\n  return Math.min(m,3.5);\n}\nasync function refreshWeather(){\n  const names=Object.keys(D.dynamicCentroids);\n  if(!names.length) return;\n  const lats=names.map(n=>D.dynamicCentroids[n].lat).join(\',\');\n  const lons=names.map(n=>D.dynamicCentroids[n].lon).join(\',\');\n  const url=`https://api.open-meteo.com/v1/forecast?latitude=${lats}&longitude=${lons}`+\n   `&hourly=precipitation,snowfall,temperature_2m,visibility,wind_gusts_10m,is_day,weather_code`+\n   `&forecast_days=${Math.min(7,Math.ceil(D.hours/24))}&timezone=America%2FIndiana%2FIndianapolis`;\n  try{\n    let payload=await (await fetch(url)).json();\n    if(!Array.isArray(payload)) payload=[payload];\n    names.forEach((name,i)=>{\n      const h=payload[i].hourly; let total=0;\n      for(let k=0;k<Math.min(D.hours,h.time.length);k++){\n        const ts=new Date(h.time[k]);\n        const ex=D.exposure[((ts.getDay()+6)%7)*24+ts.getHours()];\n        total+=wmult(h.precipitation[k],h.snowfall[k],h.temperature_2m[k],\n                     h.visibility[k],h.wind_gusts_10m[k],h.is_day[k],h.weather_code[k])*ex;\n      }\n      const c=D.counties[name];\n      c.lift=total/D.hours;\n    });\n    recolor();\n    document.getElementById(\'livestatus\').textContent=\'live weather: updated \'+new Date().toLocaleTimeString();\n  }catch(e){\n    document.getElementById(\'livestatus\').textContent=\'live weather: refresh failed (showing last data)\';\n  }\n}\nfunction recolor(){\n  Object.values(D.counties).forEach(c=>{ c._live=c.opportunity*(c.lift||1)*D.hours*c.incBoost; });\n  const mx=Math.max(...Object.values(D.counties).map(c=>c._live));\n  Object.entries(D.counties).forEach(([n,c])=>{c.risk=100*c._live/mx; if(c.fips&&byFips[c.fips])byFips[c.fips].risk=c.risk;});\n  render();\n}\nrefreshWeather();\nsetInterval(refreshWeather, 15*60*1000);\n\n// ---------- LIVE MODE: re-pull incidents from the newest pipeline build ----\n// Same-origin fetch of live_markers.json (republished by every Actions run;\n// no API keys in the page). Freshness is bounded by the pipeline cadence.\nasync function refreshIncidents(){\n  try{\n    const r=await fetch(\'live_markers.json?ts=\'+Date.now(),{cache:\'no-store\'});\n    if(!r.ok) return;\n    const j=await r.json();\n    if(!j || j.generated===D.generated) return; // same build, nothing new\n    D.live=j.live||D.live;\n    D.trail=j.trail||D.trail;\n    Object.entries(j.counties||{}).forEach(([n,u])=>{\n      const c=D.counties[n];\n      if(c){c.events=u.events;c.incBoost=u.incBoost;c.trailing=u.trailing;}\n    });\n    D.generated=j.generated;\n    drawLive(); drawTrail(); recolor();\n    document.getElementById(\'incstatus\').textContent=\n      \'incidents: pipeline run of \'+String(j.generated).replace(\'T\',\' \').slice(0,16);\n  }catch(e){/* offline / local file view — keep build-time data */}\n}\nsetInterval(refreshIncidents, 5*60*1000);\n</script></body></html>\n"""\n'
_FILES['deploy.py'] = '"""\nTranslate county risk into an ad plan (v2).\n\nOutputs:\n  budget_shares : metro-level blend of static Phase 2 shares and live\n                  county risk (counties roll up via COUNTY_TO_METRO;\n                  unmapped counties form the \'other_in\' bucket, reported\n                  but excluded from the Phase 2 blend).\n  county_targets: ranked county list for Google Ads county location\n                  targeting, with suggested within-budget weight.\n  cluster_mix   : per-metro keyword-cluster mix from Phase 2 efficiency.\n  dayparting    : high-risk hours per metro with suggested bid adjustments.\n"""\nfrom __future__ import annotations\n\nimport datetime as _dt\nimport html as _html\n\nimport pandas as pd\n\nimport config\n\n\ndef load_phase2():\n    prio = pd.read_csv(config.PHASE2_PRIORITY_CSV)\n    eff = pd.read_csv(config.PHASE2_EFFICIENCY_CSV)\n    return prio, eff\n\n\ndef budget_shares(county_scores: pd.DataFrame) -> pd.DataFrame:\n    live = county_scores.groupby("metro")["risk_score"].sum()\n    live_metros = live.drop(index="other_in", errors="ignore")\n    live_metros = live_metros / live_metros.sum()\n    w = config.DYNAMIC_WEIGHT\n    rows = []\n    for metro, static in config.STATIC_SHARES.items():\n        dyn = float(live_metros.get(metro, 0))\n        rows.append({"metro": metro, "static_share": static,\n                     "live_risk_share": round(dyn, 3),\n                     "blended_share": (1 - w) * static + w * dyn})\n    df = pd.DataFrame(rows)\n    df["blended_share"] = (df["blended_share"]\n                           / df["blended_share"].sum()).round(3)\n    df["shift_vs_static"] = (df["blended_share"]\n                             - df["static_share"]).round(3)\n    return df.sort_values("blended_share", ascending=False)\n\n\ndef county_targets(county_scores: pd.DataFrame, top_n: int = 30\n                   ) -> pd.DataFrame:\n    t = county_scores.head(top_n).copy()\n    t["within_plan_weight"] = (t["risk_score"]\n                               / t["risk_score"].sum()).round(3)\n    t["ads_location"] = t["county"] + " County, Indiana"\n    return t[["county", "metro", "risk_score", "weather_lift",\n              "active_events", "trailing_weight", "within_plan_weight",\n              "ads_location"]]\n\n\ndef cluster_mix(eff: pd.DataFrame) -> pd.DataFrame:\n    e = eff.copy()\n    e["mix"] = e.groupby("metro")["searches_per_1000usd"].transform(\n        lambda s: s / s.sum())\n    return e.sort_values(["metro", "mix"], ascending=[True, False])[\n        ["metro", "cluster", "monthly_searches", "est_cpc", "mix"]]\n\n\ndef daypart(county_hourly: pd.DataFrame,\n            county_scores: pd.DataFrame) -> pd.DataFrame:\n    """Opportunity-weighted metro hourly risk -> hours above the 75th\n    percentile with a +10%..+60% bid adjustment."""\n    h = county_hourly.merge(\n        county_scores[["county", "metro", "opportunity_score"]],\n        on="county", how="left")\n    h["w_risk"] = h["hour_risk"] * h["opportunity_score"]\n    mh = (h.groupby(["metro", "time"])["w_risk"].sum()\n          .rename("hour_risk").reset_index())\n    out = []\n    for metro, grp in mh.groupby("metro"):\n        q75 = grp["hour_risk"].quantile(0.75)\n        med = max(grp["hour_risk"].median(), 1e-9)\n        hot = grp[grp["hour_risk"] >= q75].copy()\n        hot["bid_adj_pct"] = ((hot["hour_risk"] / med - 1) * 100\n                              ).clip(10, 60).round(0)\n        out.append(hot)\n    return pd.concat(out).sort_values(["metro", "time"])\n\n\n# ---------------------------------------------------------------------------\n# Weekly ad ops sheet — plain-English one-pager for whoever runs Google Ads\n# ---------------------------------------------------------------------------\nADOPS_SNAPSHOT_DAYS = 7          # movers are measured against a snapshot\nADOPS_MIN_MOVE_PP = 0.10         # this old; refreshed once it exceeds the\n                                 # window. Movers under 0.10 pp are noise.\n\nMETRO_LABELS = {\n    "indianapolis": "Indianapolis", "indy": "Indianapolis",\n    "fortwayne": "Fort Wayne",\n    "nwindiana": "NW Indiana", "southbend": "South Bend",\n    "lafayette": "Lafayette", "evansville": "Evansville",\n    "other_in": "Rest of state",\n}\n\n\ndef _esc(x) -> str:\n    return _html.escape(str(x))\n\n\ndef _metro_label(m: str) -> str:\n    return METRO_LABELS.get(str(m), str(m))\n\n\ndef _daypart_ranges(parts: pd.DataFrame, metro: str,\n                    max_ranges: int = 4) -> list[str]:\n    """Collapse a metro\'s hot hours into ranges like\n    \'Tue 06:00-09:00 (bid +35%)\', strongest first."""\n    g = parts[parts["metro"] == metro].sort_values("time")\n    if g.empty:\n        return []\n    ranges, cur = [], None\n    for _, r in g.iterrows():\n        t = pd.Timestamp(r["time"])\n        if (cur is not None and t.date() == cur["date"]\n                and t.hour == cur["end"]):\n            cur["end"] = t.hour + 1\n            cur["adj"] = max(cur["adj"], float(r["bid_adj_pct"]))\n        else:\n            if cur is not None:\n                ranges.append(cur)\n            cur = {"date": t.date(), "day": t.strftime("%a"),\n                   "start": t.hour, "end": t.hour + 1,\n                   "adj": float(r["bid_adj_pct"])}\n    if cur is not None:\n        ranges.append(cur)\n    ranges.sort(key=lambda x: -x["adj"])\n    return ["%s %02d:00-%02d:00 (bid +%.0f%%)"\n            % (x["day"], x["start"], x["end"], x["adj"])\n            for x in ranges[:max_ranges]]\n\n\ndef _metro_why(scores: pd.DataFrame, metro: str) -> str:\n    """One line on what is driving a metro: its two riskiest counties."""\n    g = scores[scores["metro"] == metro].head(2)\n    bits = []\n    for _, r in g.iterrows():\n        d = []\n        if float(r.get("active_events", 0)) > 0:\n            d.append("%.1f live event wt" % float(r["active_events"]))\n        if float(r.get("trailing_weight", 0)) > 0:\n            d.append("%.1f recent-crash wt" % float(r["trailing_weight"]))\n        wl = float(r.get("weather_lift", 1.0))\n        if abs(wl - 1.0) >= 0.05:\n            d.append("weather x%.2f" % wl)\n        la = float(r.get("learned_adj", 1.0))\n        if abs(la - 1.0) >= 0.05:\n            d.append("learned adj x%.2f" % la)\n        bits.append("%s (risk %.0f%s)" % (\n            r["county"], float(r["risk_score"]),\n            "; " + ", ".join(d) if d else ""))\n    return " · ".join(bits) if bits else "quiet"\n\n\ndef ad_ops_html(scores: pd.DataFrame, shares: pd.DataFrame,\n                mix: pd.DataFrame, parts: pd.DataFrame,\n                badges: dict, hours: int, prev: dict\n                ) -> tuple[str, dict | None]:\n    """Build output/ad_ops.html. Returns (html, new_snapshot_or_None).\n\n    prev is the last stored snapshot ({\'date\': iso, \'shares\': {county:\n    share}}); a new snapshot is returned only when prev is absent or\n    older than ADOPS_SNAPSHOT_DAYS (rolling weekly comparison)."""\n    now = _dt.datetime.now()\n    tot = float(scores["risk_score"].sum()) or 1.0\n    cur_shares = {str(r["county"]): float(r["risk_score"]) / tot\n                  for _, r in scores.iterrows()}\n\n    # Watch list vs last snapshot\n    prev_shares = (prev or {}).get("shares") or {}\n    prev_date = str((prev or {}).get("date") or "")[:10]\n    movers_up, movers_dn = [], []\n    if prev_shares:\n        deltas = [(c, (cur_shares.get(c, 0.0) - float(p)) * 100)\n                  for c, p in prev_shares.items()]\n        deltas += [(c, cur_shares[c] * 100) for c in cur_shares\n                   if c not in prev_shares]\n        deltas = [d for d in deltas if abs(d[1]) >= ADOPS_MIN_MOVE_PP]\n        deltas.sort(key=lambda x: -x[1])\n        movers_up = deltas[:4]\n        movers_dn = sorted([d for d in deltas if d[1] < 0],\n                           key=lambda x: x[1])[:4]\n\n    snap = None\n    age_ok = False\n    if prev and prev.get("date"):\n        try:\n            age_ok = (now - _dt.datetime.fromisoformat(\n                prev["date"])).days < ADOPS_SNAPSHOT_DAYS\n        except Exception:  # noqa: BLE001\n            age_ok = False\n    if not age_ok:\n        snap = {"date": now.isoformat(timespec="seconds"),\n                "shares": {c: round(s, 5) for c, s in cur_shares.items()}}\n\n    css = ("body{font-family:Segoe UI,Arial,sans-serif;max-width:860px;"\n           "margin:24px auto;padding:0 16px;color:#222;line-height:1.45}"\n           "h1{font-size:22px;margin-bottom:2px}h2{font-size:16px;"\n           "border-bottom:2px solid #b91c1c;padding-bottom:3px;"\n           "margin-top:26px}table{border-collapse:collapse;width:100%;"\n           "font-size:13px}th,td{border:1px solid #ddd;padding:5px 8px;"\n           "text-align:left}th{background:#f5f5f5}small,.muted{color:#666}"\n           ".up{color:#b91c1c;font-weight:600}.dn{color:#1d4ed8;"\n           "font-weight:600}.foot{margin-top:28px;padding:10px;"\n           "background:#fef2f2;border:1px solid #fecaca;font-size:12px}")\n    H = ["<!DOCTYPE html><html><head><meta charset=\'utf-8\'>"\n         "<title>Weekly Ad Ops Sheet</title><style>" + css + "</style>"\n         "</head><body>",\n         "<h1>Weekly Ad Ops Sheet — Indiana Accident Forecaster</h1>",\n         "<div class=\'muted\'>Generated %s · %d-hour risk horizon · "\n         "companion to the <a href=\'index.html\'>live risk map</a></div>"\n         % (now.strftime("%a %b %d, %Y %H:%M"), hours)]\n\n    # 1. Budget split\n    H.append("<h2>1 · Metro budget split this week</h2><table><tr>"\n             "<th>Metro</th><th>Spend share</th><th>vs static plan</th>"\n             "<th>What\'s driving it (top counties)</th></tr>")\n    for _, r in shares.iterrows():\n        shift = float(r["shift_vs_static"])\n        arrow = ("<span class=\'up\'>&#9650; +%.1f pp</span>" % (shift * 100)\n                 if shift > 0.0005 else\n                 "<span class=\'dn\'>&#9660; %.1f pp</span>" % (shift * 100)\n                 if shift < -0.0005 else "&#8212; flat")\n        H.append("<tr><td><b>%s</b></td><td>%.0f%%</td><td>%s</td>"\n                 "<td><small>%s</small></td></tr>"\n                 % (_esc(_metro_label(r["metro"])),\n                    float(r["blended_share"]) * 100, arrow,\n                    _esc(_metro_why(scores, r["metro"]))))\n    H.append("</table><small>Shares blend the static Phase 2 plan with "\n             "live county risk (max %.0f%% dynamic shift).</small>"\n             % (config.DYNAMIC_WEIGHT * 100))\n\n    # 2. When to bid up\n    H.append("<h2>2 · When to bid up (next %dh)</h2><table>"\n             "<tr><th>Metro</th><th>Raise bids during</th></tr>" % hours)\n    for m in shares["metro"]:\n        rng = _daypart_ranges(parts, m)\n        if rng:\n            H.append("<tr><td><b>%s</b></td><td>%s</td></tr>"\n                     % (_esc(_metro_label(m)), _esc(" · ".join(rng))))\n    H.append("</table><small>Hours above the metro\'s 75th-percentile "\n             "risk; suggested bid adjustment in parentheses.</small>")\n\n    # 3. Keyword lean\n    H.append("<h2>3 · Keyword cluster lean</h2><table><tr><th>Metro</th>"\n             "<th>Lead clusters (share of mix · est. CPC)</th></tr>")\n    for m, g in mix.groupby("metro", sort=False):\n        top = g.head(3)\n        cells = " · ".join("%s (%.0f%% · $%.2f)" % (\n            row["cluster"], float(row["mix"]) * 100, float(row["est_cpc"]))\n            for _, row in top.iterrows())\n        H.append("<tr><td><b>%s</b></td><td><small>%s</small></td></tr>"\n                 % (_esc(_metro_label(m)), _esc(cells)))\n    H.append("</table>")\n\n    # 4. Vehicle-type counties\n    truck = (badges or {}).get("truck") or {}\n    ride = (badges or {}).get("ride") or {}\n    if truck or ride:\n        H.append("<h2>4 · Vehicle-type counties</h2><ul>")\n        for c in sorted(truck):\n            H.append("<li>&#128667; <b>%s</b> — truck-tilted (%s): lean "\n                     "on truck-accident keywords here.</li>"\n                     % (_esc(c), _esc(truck[c])))\n        for c in sorted(ride):\n            H.append("<li>&#128661; <b>%s</b> — rideshare focus (%s).</li>"\n                     % (_esc(c), _esc(ride[c])))\n        H.append("</ul>")\n\n    # 5. Watch list\n    H.append("<h2>5 · Watch list — biggest movers</h2>")\n    if prev_shares:\n        H.append("<div class=\'muted\'><small>Change in share of statewide "\n                 "risk vs snapshot of %s (pct points).</small></div><ul>"\n                 % _esc(prev_date))\n        for c, d in movers_up:\n            if d > 0:\n                H.append("<li><span class=\'up\'>&#9650; %+.2f pp</span> "\n                         "<b>%s</b></li>" % (d, _esc(c)))\n        for c, d in movers_dn:\n            H.append("<li><span class=\'dn\'>&#9660; %+.2f pp</span> "\n                     "<b>%s</b></li>" % (d, _esc(c)))\n        if not movers_up and not movers_dn:\n            H.append("<li>No county moved more than %.2f pp — steady "\n                     "week.</li>" % ADOPS_MIN_MOVE_PP)\n        H.append("</ul>")\n    else:\n        H.append("<p><small>First snapshot recorded — movers will appear "\n                 "here starting next week.</small></p>")\n\n    H.append("<div class=\'foot\'><b>Compliance (Ind. Prof. Cond. R. "\n             "7.1&#8211;7.3):</b> all targeting stays at the geography / "\n             "road-condition level &#8212; county budgets, dayparts, and "\n             "keyword themes only. No incident-specific ad creative, no "\n             "retargeting tied to a crash, no victim identification.</div>"\n             "</body></html>")\n    return "\\n".join(H), snap\n'
_FILES['ledger.py'] = '"""\nLong-term crash ledger (learned county baseline adjustment).\n\nEvery crash our feeds record — from any full build or 5-minute poll — is\ntallied by county and month under the reserved "_ledger" key inside\nincident_history.json (the file the workflow already commits, so nothing\nnew to configure and the tally never fades, unlike trailing memory).\n\nOnce the statewide sample passes LEDGER_MIN_TOTAL, each county\'s observed\ncrash share is compared with its EMS-baseline share and turned into a\ngentle empirical-Bayes multiplier:\n\n    expected_c = total_observed * baseline_share_c\n    factor_c   = clip((observed_c + K) / (expected_c + K), CAP_LO, CAP_HI)\n\nK (LEDGER_PRIOR_K) shrinks small samples toward 1.0 so a rural county\nwith 3 observed crashes isn\'t judged on noise. The caps are deliberately\ntight: the feeds over-represent INDOT highways and metro roads (511\ncovers only state-managed routes; TomTom probe density is urban-tilted),\nso the EMS baseline stays the anchor and this only nudges it.\n"""\nfrom __future__ import annotations\n\nimport datetime as dt\n\nimport config\n\n\ndef _ledger(hist: dict) -> dict:\n    led = hist.get("_ledger")\n    if not isinstance(led, dict) or "months" not in led:\n        led = {"since": dt.datetime.now().isoformat(timespec="seconds"),\n               "months": {}}\n        hist["_ledger"] = led\n    return led\n\n\ndef is_truck(text: str) -> bool:\n    t = f" {str(text).lower()} "\n    return any(k in t for k in config.TRUCK_KEYWORDS)\n\n\ndef _cell(bucket: dict, county: str) -> dict:\n    """County cell within a month bucket; migrates the original plain-int\n    format ({county: 3}) to {county: {"n": 3, "truck": 0}} on touch."""\n    cur = bucket.get(county)\n    if isinstance(cur, dict):\n        return cur\n    cell = {"n": int(cur or 0), "truck": 0}\n    bucket[county] = cell\n    return cell\n\n\ndef record(hist: dict, new_crash_entries: list[dict],\n           now: dt.datetime | None = None) -> None:\n    """Tally newly-first-seen crashes into hist["_ledger"] (in place),\n    tracking truck involvement from the event text."""\n    if not new_crash_entries:\n        return\n    led = _ledger(hist)\n    month = (now or dt.datetime.now()).strftime("%Y-%m")\n    bucket = led["months"].setdefault(month, {})\n    for e in new_crash_entries:\n        c = e.get("county")\n        if not c:\n            continue\n        cell = _cell(bucket, c)\n        cell["n"] += 1\n        if is_truck(f\'{e.get("type", "")} {e.get("desc", "")}\'):\n            cell["truck"] += 1\n\n\ndef totals(hist: dict) -> tuple[dict, int, str]:\n    led = _ledger(hist)\n    obs: dict[str, float] = {}\n    for bucket in led["months"].values():\n        for c, n in bucket.items():\n            obs[c] = obs.get(c, 0) + (n["n"] if isinstance(n, dict) else n)\n    return obs, int(sum(obs.values())), led["since"]\n\n\ndef truck_stats(hist: dict) -> dict[str, tuple[int, int]]:\n    """{county: (truck_involved, total)} across the whole archive."""\n    led = _ledger(hist)\n    out: dict[str, list[int]] = {}\n    for bucket in led["months"].values():\n        for c, n in bucket.items():\n            t = n["truck"] if isinstance(n, dict) else 0\n            tot = n["n"] if isinstance(n, dict) else n\n            cur = out.setdefault(c, [0, 0])\n            cur[0] += t\n            cur[1] += tot\n    return {c: (v[0], v[1]) for c, v in out.items()}\n\n\ndef load_baseline() -> dict[str, tuple[int, int]]:\n    """{county: (truck, total)} from the official background table\n    (config.BASELINE_CRASH_CSV, from the ICJI/IU-PPI ARIES county\n    profiles). Missing file or zero-total rows are skipped."""\n    import csv\n    import os\n    out = {}\n    if not os.path.exists(config.BASELINE_CRASH_CSV):\n        return out\n    try:\n        with open(config.BASELINE_CRASH_CSV) as f:\n            for row in csv.DictReader(f):\n                try:\n                    n = int(float(row.get("total_crashes") or 0))\n                    raw_t = (row.get("truck_crashes") or "").strip()\n                    t = int(float(raw_t)) if raw_t else None  # blank=unknown\n                except ValueError:\n                    continue\n                if n > 0 and row.get("county"):\n                    out[row["county"].strip()] = (t, n)\n    except Exception as e:  # noqa: BLE001\n        print(f"[warn] baseline crash table unreadable: {e}")\n    return out\n\n\ndef truck_badges(hist: dict,\n                 baseline: dict[str, tuple[int, int]] | None = None\n                 ) -> dict[str, str]:\n    """{county: reason} for counties notably truck-crash-prone, judged on\n    official background data (when the baseline table is present) blended\n    with everything the live feeds have archived."""\n    baseline = baseline or {}\n    feed = truck_stats(hist)\n    out = {}\n    for c in set(feed) | set(baseline):\n        ft, fn = feed.get(c, (0, 0))\n        bt, bn = baseline.get(c, (None, 0))\n        if bt is None:  # totals known but truck split unknown: badge on\n            bt = bn = 0  # feed evidence alone, don\'t dilute the share\n        t, n = ft + bt, fn + bn\n        if n >= config.TRUCK_BADGE_MIN_N and t / n >= config.TRUCK_BADGE_MIN_SHARE:\n            src = ("official baseline + our archive" if bn and fn\n                   else "official baseline" if bn else "our archive")\n            out[c] = f"{t} of {n} crashes truck-involved ({src})"\n    return out\n\n\ndef official_factors(baseline: dict[str, tuple[int | None, int]],\n                     ems_shares: dict[str, float]) -> dict[str, float]:\n    """Background-baseline county adjustment from official ARIES totals:\n    each county\'s share of officially reported crashes vs its EMS-injury\n    share, square-rooted (official totals include property-damage-only\n    crashes, so they get half weight against the injury-anchored EMS\n    baseline) and capped. Applied only when the table covers nearly the\n    whole state, so partial tables can\'t skew relative shares."""\n    if len(baseline) < 80:\n        return {}\n    total = sum(n for _t, n in baseline.values())\n    if total <= 0:\n        return {}\n    lo, hi = config.LEDGER_CAP\n    out = {}\n    for c, share in ems_shares.items():\n        if c not in baseline or share <= 0:\n            continue\n        ratio = (baseline[c][1] / total) / share\n        out[c] = round(min(max(ratio ** 0.5, lo), hi), 3)\n    return out\n\n\ndef factors(hist: dict, baseline_shares: dict[str, float]\n            ) -> tuple[dict[str, float], dict]:\n    """({county: multiplier}, meta). Factors stay empty (no adjustment)\n    while the statewide sample is below LEDGER_MIN_TOTAL."""\n    obs, total, since = totals(hist)\n    meta = {"total": total, "since": since}\n    if total < config.LEDGER_MIN_TOTAL:\n        return {}, meta\n    k = config.LEDGER_PRIOR_K\n    lo, hi = config.LEDGER_CAP\n    out = {}\n    for county, share in baseline_shares.items():\n        expected = total * share\n        f = (obs.get(county, 0) + k) / (expected + k)\n        out[county] = round(min(max(f, lo), hi), 3)\n    return out, meta\n'

for _p, _t in _FILES.items():
    with open(_p, 'w') as _f:
        _f.write(_t)

# Modules are now guaranteed-correct on disk; import and run.
import importlib, sys
for _m in ('config','sources','memory','ledger','model','geo','mapbuild','deploy'):
    if _m in sys.modules:
        importlib.reload(sys.modules[_m])
import config, deploy, geo, ledger, mapbuild, memory, model, sources

def run(hours: int = 48, outdir: str = "output"):
    os.makedirs(outdir, exist_ok=True)
    print("Loading county opportunity table ...")
    counties = sources.load_counties()
    print("Fetching county boundaries ...")
    geodata = geo.fetch_indiana_geojson()
    centroids = sources.county_centroids(geodata, list(counties["county"]))
    print("Fetching weather for %d counties (one batched call) ..."
          % len(centroids))
    weather = sources.fetch_weather(hours, centroids)
    hist = memory.load()
    print("Fetching live incidents ...")
    incidents, live_events = sources.fetch_incidents(
        geodata, list(counties["county"]),
        tomtom_cache=hist.setdefault("_tomtom", {}))
    before_ids = set(hist)
    hist = memory.update(hist, live_events)
    ledger.record(hist, [hist[i] for i in set(hist) - before_ids
                         if hist[i].get("category") == "crash"])
    memory.save(hist)
    live_ids = {memory.event_id(e) for e in live_events}
    trail = memory.trailing(hist, live_ids)
    trailing_scores = memory.county_trailing_scores(trail)
    if trail:
        print(f"  {len(trail)} trailing incident(s) in memory "
              f"(top: {trail[0]['type']} in {trail[0]['county']}, "
              f"{trail[0]['age_h']:.0f}h ago, importance "
              f"{trail[0]['importance']:.2f})")

    opp = counties.set_index("county")["opportunity_score"]
    base_shares = (opp / opp.sum()).to_dict()
    baseline_tbl = ledger.load_baseline()
    if baseline_tbl:
        print(f"[info] official baseline crash table loaded: "
              f"{len(baseline_tbl)} counties")
    led_factors, led_meta = ledger.factors(hist, base_shares)
    official = ledger.official_factors(baseline_tbl, base_shares)
    if official:
        lo, hi = config.LEDGER_CAP
        led_factors = {c: round(min(max(
            official.get(c, 1.0) * led_factors.get(c, 1.0), lo), hi), 3)
            for c in set(official) | set(led_factors)}
        print(f"[info] official ARIES baseline adjusting "
              f"{len(official)} county baselines (blended with the "
              f"live-feed ledger, cap x{lo}-{hi})")
    if led_factors:
        print(f"[info] crash ledger: {led_meta['total']} crash(es) archived "
              f"since {str(led_meta['since'])[:10]} — county baselines "
              f"adjusted (cap x{config.LEDGER_CAP[0]}-{config.LEDGER_CAP[1]})")
    else:
        print(f"[info] crash ledger: {led_meta['total']} crash(es) archived "
              f"(learning phase; adjustments begin at "
              f"{config.LEDGER_MIN_TOTAL} statewide)")
    scores, hourly = model.score(counties, weather, incidents, hours,
                                 trailing_scores, led_factors)
    print("Fetching commuter origin-destination data (Census LODES; "
          "~1-2 min first run) ...")
    flows = geo.fetch_flows()
    origins = geo.top_origins(flows, geodata)
    prio, eff = deploy.load_phase2()
    shares = deploy.budget_shares(scores)
    targets = deploy.county_targets(scores)
    mix = deploy.cluster_mix(eff)
    parts = deploy.daypart(hourly, scores)

    scores.to_csv(f"{outdir}/county_risk.csv", index=False)
    targets.to_csv(f"{outdir}/county_targets.csv", index=False)
    shares.to_csv(f"{outdir}/budget_shares.csv", index=False)
    mix.to_csv(f"{outdir}/cluster_mix.csv", index=False)
    parts.to_csv(f"{outdir}/dayparting.csv", index=False)
    # Only crashes get markers: live ones filtered in-page via
    # MAP_MIN_MARKER_WEIGHT, recent ones filtered here from trailing
    # memory. Every event still shades its county and is itemized in
    # its panel.
    truck = dict(ledger.truck_badges(hist, baseline_tbl))
    for c in config.TRUCK_COUNTIES_MANUAL:
        truck.setdefault(c, "designated from firm case history")
    ride = {c: "designated from firm case history"
            for c in config.RIDESHARE_COUNTIES_MANUAL}
    if truck or ride:
        print(f"[info] vehicle badges: truck={sorted(truck) or '-'} "
              f"rideshare={sorted(ride) or '-'}")
    prev = hist.get("_adops") or {}
    ops_html, snap = deploy.ad_ops_html(
        scores, shares, mix, parts,
        {"truck": truck, "ride": ride}, hours, prev)
    with open(f"{outdir}/ad_ops.html", "w") as f:
        f.write(ops_html)
    if snap is not None:
        hist["_adops"] = snap
        memory.save(hist)
    print("[info] ad ops sheet written: %s/ad_ops.html (movers vs %s)"
          % (outdir, (prev.get("date","")[:10] or "first snapshot")))
    crash_trail = [e for e in trail
                   if e.get("category") == "crash"
                   or (not e.get("category") and sources.classify_event(
                       f"{e.get('type', '')} {e.get('desc', '')}")[1]
                       >= config.MAP_MIN_MARKER_WEIGHT)]
    mapbuild.build_map(scores, geodata, origins,
                       badges={"truck": truck, "ride": ride},
                       path=f"{outdir}/risk_map.html", hours=hours,
                       trail=crash_trail, live=live_events)

    print("\n=== Blended budget shares (next %d h) ===" % hours)
    print(shares.to_string(index=False))
    print("\n=== Top 10 counties ===")
    print(targets.head(10).to_string(index=False))
    print(f"\nOutputs written to ./{outdir} (open risk_map.html).")
    return scores, shares, targets, mix, parts


def poll_only():
    """Lightweight incident-only poll: 511 -> incident_history.json and
    exit. No TomTom (protects its daily request quota), no weather, no
    map. Run every 5 minutes between full builds so short-lived crash
    reports get captured into trailing memory instead of being missed."""
    counties = sources.load_counties()
    geodata = geo.fetch_indiana_geojson()
    _, live_events = sources.fetch_incidents(
        geodata, list(counties["county"]), include_tomtom=False)
    hist = memory.load()
    before_ids = set(hist)
    hist = memory.update(hist, live_events)
    new_crashes = [hist[i] for i in set(hist) - before_ids
                   if hist[i].get("category") == "crash"]
    ledger.record(hist, new_crashes)
    memory.save(hist)
    crashes = sum(1 for e in live_events
                  if e.get("category") == "crash")
    print(f"[info] poll-only: {len(live_events)} live event(s), "
          f"{crashes} crash(es), {len(new_crashes)} new to the ledger; "
          f"history {len(before_ids)} -> {len(hist)} entries")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--hours", type=int, default=48)
    ap.add_argument("--poll-only", action="store_true",
                    help="511-only incident poll; update history and exit")
    args = ap.parse_args()
    if args.poll_only:
        poll_only()
    else:
        run(args.hours)
